export const JUST_BECAUSE_ENTRIES = [
  { id: "c3d5d4c3-346f-4c9c-bf86-b65a330e7589", sisterIndex: 0, author: "Sr. Purity Nkatha", topic: "Jesus", sentiment: {"en":"His name is Love—so even my darkest night surrenders to dawn, just because.","it":"Il Suo nome è Amore—così anche la mia notte più buia si arrende all’aurora, solo perché."} },
  { id: "8d9ea211-bd8f-8d9e-6bd8-000080881f9e", sisterIndex: 1, author: "Sr. Mary Japheth", topic: "Jesus", sentiment: {"en":"He walked into my ordinary morning and my whole day changed shape, just because.","it":"È entrato nella mia ordinaria mattina e la mia giornata ha cambiato forma, solo perché."} },
  { id: "ce4c3e12-826a-ce4c-c826-000059f0bc78", sisterIndex: 2, author: "Sr. Christine Musoga", topic: "Jesus", sentiment: {"en":"In each whisper of mercy I recognise His voice, thin but unmistakable, just because.","it":"In ogni sussurro di misericordia riconosco la Sua voce, sottile ma inequivocabile, solo perché."} },
  { id: "057f1fdd-9a09-43ba-84d2-7f64bc922bf1", sisterIndex: 3, author: "Sr. Priscilla Kanini", topic: "Jesus", sentiment: {"en":"Every morning dawns anew—because He rose from the grave, just because.","it":"Ogni mattina nasce nuovo—perché è risorto dalla tomba, solo perché."} },
  { id: "6ee2e8ad-70b1-6ee2-670b-00009384981c", sisterIndex: 4, author: "Sr. Aniceta Kaare", topic: "Jesus", sentiment: {"en":"He taught me to forgive before I understood the wound, just because.","it":"Mi ha insegnato a perdonare prima che capissi la ferita, solo perché."} },
  { id: "b66aa66a-9924-b66a-4992-00009d8e3f4e", sisterIndex: 5, author: "Sr. Anastasia Nkubitu", topic: "Jesus", sentiment: {"en":"His love is not a feeling I cultivate; it is a fact I stand on, just because.","it":"Il Suo amore non è un sentimento che coltivo; è un fatto su cui mi appoggio, solo perché."} },
  { id: "3c2d773e-7440-4641-846e-4634cbbf8f48", sisterIndex: 6, author: "Sr. Pauline", topic: "Jesus", sentiment: {"en":"In every drop of His blood, my worth is revealed—just because He loved me first.","it":"In ogni goccia del Suo sangue, il mio valore si rivela—solo perché mi ha amato per primo."} },
  { id: "520a61cb-b21d-520a-5b21-000092ffd3d6", sisterIndex: 7, author: "Sr. Beth", topic: "Jesus", sentiment: {"en":"He calls me by name in the middle of the noise, and I am allowed to answer, just because.","it":"Mi chiama per nome in mezzo al rumore, e mi è permesso rispondere, solo perché."} },
  { id: "3f40ce53-a88f-3f40-8a88-0000df8866dc", sisterIndex: 8, author: "Sr. Frida Mburugu", topic: "Jesus", sentiment: {"en":"His faithfulness has outlasted every promise I failed to keep, just because.","it":"La Sua fedeltà ha superato ogni promessa che non sono riuscita a mantenere, solo perché."} },
  { id: "05820405-6717-4fb3-93d6-34f0816a7fdf", sisterIndex: 9, author: "Sr. Maureen", topic: "Jesus", sentiment: {"en":"His cross bears my hope, and I am lifted—just because He carried it for all.","it":"La Sua croce porta la mia speranza, e io mi sollevo—solo perché l’ha portata per tutti."} },
  { id: "14fb8187-76ea-4668-9959-c7d9b37c8039", sisterIndex: 10, author: "Sr. Dorothy", topic: "Jesus", sentiment: {"en":"His mercy knows no boundaries; I rest in His embrace—just because.","it":"La Sua misericordia non conosce confini; trovo riposo nel Suo abbraccio—solo perché."} },
  { id: "f9c32fc2-d9e6-f9c3-3d9e-0000de60f624", sisterIndex: 11, author: "Sr. Sofia", topic: "Jesus", sentiment: {"en":"He never asked me to be strong every day; only to lean, just because.","it":"Non mi ha mai chiesto di essere forte ogni giorno; solo di appoggiarmi, solo perché."} },
  { id: "39ebe9dc-8724-39eb-2872-00003bc96ef8", sisterIndex: 12, author: "Sr. Agnes Muthoni", topic: "Jesus", sentiment: {"en":"His presence is the warmth I feel in a cold corridor, just because.","it":"La Sua presenza è il calore che sento in un corridoio freddo, solo perché."} },
  { id: "0c3eed39-d7cf-406a-9e64-65b22f5c8c08", sisterIndex: 13, author: "Sr. Mary Mwikali Matheka", topic: "Jesus", sentiment: {"en":"Within the shadow of His wounds, I find healing—because His love has no end, just because.","it":"Nell’ombra delle Sue ferite, trovo guarigione—perché il Suo amore non ha fine, solo perché."} },
  { id: "371c383b-6955-371c-b695-00004357516e", sisterIndex: 14, author: "Sr. Jane Makanda", topic: "Jesus", sentiment: {"en":"He forgave me before I had the courage to ask, just because.","it":"Mi ha perdonato prima che io avessi il coraggio di chiedere, solo perché."} },
  { id: "2e8418ec-1a08-2e84-31a0-00003bd702e4", sisterIndex: 15, author: "Sr. Rose Kanathi", topic: "Jesus", sentiment: {"en":"His name is peace; in every storm I find calm—just because.","it":"Il Suo nome è pace; in ogni tempesta trovo calma—solo perché."} },
  { id: "5460165d-62fd-4b3e-96c4-c8543b982ad1", sisterIndex: 16, author: "Sr. Andreina Stradiotto", topic: "Jesus", sentiment: {"en":"He taught me to love my neighbour before I could love myself, just because.","it":"Mi ha insegnato ad amare il prossimo prima che sapessi amare me stessa, solo perché."} },
  { id: "e9e2cb37-86a9-e9e2-d86a-0000ea7f4d9e", sisterIndex: 17, author: "Sr. Giovanna", topic: "Jesus", sentiment: {"en":"His words are bread; I have never gone hungry after them, just because.","it":"Le Sue parole sono pane; non ho mai avuto fame dopo, solo perché."} },
  { id: "5e1a19f4-6e9c-5e1a-96e9-000042537768", sisterIndex: 18, author: "Sr. Consolata", topic: "Jesus", sentiment: {"en":"His love is the song my soul sings, because He first sang it for me—just because.","it":"Il Suo amore è il canto della mia anima, perché Lui lo ha cantato per me per primo—solo perché."} },
  { id: "a6941273-3b73-4a59-a5d5-2c6393c3e30f", sisterIndex: 19, author: "Sr. Adriana", topic: "Jesus", sentiment: {"en":"He stays awake with me in my longest night, just because.","it":"Rimane sveglio con me nella mia notte più lunga, solo perché."} },
  { id: "e1acf6c0-f108-e1ac-bf10-0000b42707c8", sisterIndex: 20, author: "Sr. Sabina Murwana", topic: "Jesus", sentiment: {"en":"His heart beats for the broken, so I find courage in my weakness—just because.","it":"Il Suo cuore batte per i fragili, così trovo coraggio nella mia debolezza—solo perché."} },
  { id: "25bde2ae-feca-4655-80ad-acfd0df98fa4", sisterIndex: 21, author: "Sr. Susan Chokera", topic: "Jesus", sentiment: {"en":"He turns my smallest yes into a life I never planned, just because.","it":"Trasforma il mio più piccolo sì in una vita che non avevo pianificato, solo perché."} },
  { id: "cb2c7c85-e14b-cb2c-8e14-00000c449dce", sisterIndex: 22, author: "Sr. Susan Kanini", topic: "Jesus", sentiment: {"en":"His light is not harsh; it is the kind that lets me see my dust and still stay, just because.","it":"La Sua luce non è dura; è quella che mi fa vedere la polvere e mi fa restare, solo perché."} },
  { id: "cf95f7ff-dc67-cf95-6dc6-000071c32b98", sisterIndex: 23, author: "Sr. Cecilia", topic: "Jesus", sentiment: {"en":"His cross bore my burdens, and I walk with lighter steps—just because.","it":"La Sua croce ha portato i miei pesi, e cammino con passi più leggeri—solo perché."} },
  { id: "210589f1-6908-4140-bf0b-ed7345573295", sisterIndex: 24, author: "Sr. Lucy Wegoki", topic: "Jesus", sentiment: {"en":"He asked me once for my yes, and I have been saying it ever since, just because.","it":"Una volta mi ha chiesto un sì, e da allora lo ripeto ogni giorno, solo perché."} },
  { id: "8c06adc5-b11f-8c06-6b11-0000b2101cda", sisterIndex: 25, author: "Sr. Angelica Kinya", topic: "Jesus", sentiment: {"en":"His silence is not absence; it is how He stays close without crowding me, just because.","it":"Il Suo silenzio non è assenza; è come rimane vicino senza opprimermi, solo perché."} },
  { id: "c3a4743e-5df4-c3a4-55df-0000f9f129ca", sisterIndex: 26, author: "Sr. Julian", topic: "Jesus", sentiment: {"en":"His mercy finds me in every season; He is always near—just because.","it":"La Sua misericordia mi trova in ogni stagione; è sempre vicino—solo perché."} },
  { id: "d26ad1bc-db2a-4110-a6f0-c27d7e150357", sisterIndex: 27, author: "Sr. Maria Carrolla", topic: "Jesus", sentiment: {"en":"He did not remove my cross, but He carried it with me, just because.","it":"Non ha tolto la mia croce, ma l’ha portata con me, solo perché."} },
  { id: "55a22f63-d2c3-55a2-9d2c-0000630bfda0", sisterIndex: 28, author: "Sr. Nancy", topic: "Jesus", sentiment: {"en":"His footsteps guide me gently—he walked the road before me, just because.","it":"I Suoi passi mi guidano dolcemente—ha percorso la strada prima di me, solo perché."} },
  { id: "4cf43a9b-aadb-4a13-a139-d195aabf8cc0", sisterIndex: 29, author: "Sr. Loredana", topic: "Jesus", sentiment: {"en":"He taught me to forgive myself as I forgive others, just because.","it":"Mi ha insegnato a perdonarmi come perdono gli altri, solo perché."} },
  { id: "46f7de27-ad55-46f7-fad5-000071987372", sisterIndex: 30, author: "Sr. Jerusha Nkatha", topic: "Jesus", sentiment: {"en":"He counts every tear, including the ones I hid, just because.","it":"Conta ogni lacrima, anche quelle che ho nascosto, solo perché."} },
  { id: "8d971992-9b42-8d97-19b4-0000101682d0", sisterIndex: 31, author: "Sr. Benedicta", topic: "Jesus", sentiment: {"en":"His wounds speak healing when words are gone—He remains my hope, just because.","it":"Le Sue ferite parlano guarigione quando le parole finiscono—Lui resta la mia speranza, solo perché."} },
  { id: "39a35935-53ca-463f-b60d-a5240759d09f", sisterIndex: 32, author: "Sr. Felicity Makena", topic: "Jesus", sentiment: {"en":"He emptied Himself for me, so I can live unashamed, just because.","it":"Si è svuotato per me, così posso vivere senza vergogna, solo perché."} },
  { id: "d26317ca-c8a8-d263-8c8a-0000a0cbdf62", sisterIndex: 33, author: "Sr. Jiunisia Kaburi", topic: "Jesus", sentiment: {"en":"His love is a gentle flame that never fades, lighting my path, just because.","it":"Il Suo amore è una fiamma gentile che non si spegne mai, illumina il mio cammino, solo perché."} },
  { id: "079a8255-c677-079a-1c67-000024bb4422", sisterIndex: 34, author: "Sr. Margaret N. Kaleli", topic: "Jesus", sentiment: {"en":"He meets me in the doorway of every new beginning, just because.","it":"Mi incontra sulla soglia di ogni nuovo inizio, solo perché."} },
  { id: "609b6a79-5d03-4a12-9118-1e9fe83c8ddd", sisterIndex: 35, author: "Sr. Mercy Kathure", topic: "Jesus", sentiment: {"en":"His home is built for the last of the last, and I am welcome in it, just because.","it":"La Sua casa è fatta per gli ultimi degli ultimi, e io ci sono benvenuta, solo perché."} },
  { id: "dc9f24ba-cd98-dc9f-ecd9-000067a1e922", sisterIndex: 36, author: "Sr. Hellen Murungi", topic: "Jesus", sentiment: {"en":"His grace finds me in the silence—softly guiding my journey, just because.","it":"La Sua grazia mi trova nel silenzio—guidando dolcemente il mio cammino, solo perché."} },
  { id: "37317857-5305-3731-5530-0000c0842b52", sisterIndex: 37, author: "Sr. Virginia Mwakiuna", topic: "Jesus", sentiment: {"en":"He gave me a name no one else can use, just because.","it":"Mi ha dato un nome che nessun altro può usare, solo perché."} },
  { id: "6d06cb5c-8bb2-6d06-48bb-0000bd9240ee", sisterIndex: 38, author: "Sr. Agatha Mkunda", topic: "Jesus", sentiment: {"en":"His heart forgave me for the worst thing I did before I confessed it, just because.","it":"Il Suo cuore mi ha perdonato per la cosa peggiore che ho fatto prima di confessarla, solo perché."} },
  { id: "e72ddeed-985a-4b2f-87f3-bd355460afe4", sisterIndex: 39, author: "Sr. Regina", topic: "Jesus", sentiment: {"en":"He teaches me to carry my questions instead of burying them, just because.","it":"Mi insegna a portare le mie domande invece di seppellirle, solo perché."} },
  { id: "a1489e5d-b96f-a148-6b96-0000f04e2732", sisterIndex: 40, author: "Sr. Dorcas", topic: "Jesus", sentiment: {"en":"He listens to the smallest voice—my quiet prayers are heard, just because.","it":"Ascolta la voce più piccola—le mie preghiere silenziose sono ascoltate, solo perché."} },
  { id: "3bbb017b-0da9-3bbb-e0da-0000e7a50cd2", sisterIndex: 41, author: "Sr. Salome Wavinya", topic: "Jesus", sentiment: {"en":"His hands were scarred so that mine would not have to be, just because.","it":"Le Sue mani erano segnate perché le mie non dovessero esserlo, solo perché."} },
  { id: "bb766c18-5caa-bb76-35ca-00002a1530b2", sisterIndex: 42, author: "Sr. Immaculate", topic: "Jesus", sentiment: {"en":"He stayed awake in Gethsemane so I could sleep peacefully, just because.","it":"È rimasto sveglio a Getsemani perché io potessi dormire in pace, solo perché."} },
  { id: "afe5c3f6-bf30-4722-8aeb-baac4ddd5e35", sisterIndex: 43, author: "Sr. Ann", topic: "Jesus", sentiment: {"en":"He turned my mourning into dancing without asking me to forget the ache, just because.","it":"Ha cambiato il mio lutto in danza senza chiedermi di dimenticare il dolore, solo perché."} },
  { id: "cf810d50-ed8e-cf81-ced8-000073bde0de", sisterIndex: 44, author: "Sr. Jane Murigi", topic: "Jesus", sentiment: {"en":"His joy is my song in the morning—every sorrow melts away, just because.","it":"La Sua gioia è il mio canto del mattino—ogni dolore si scioglie, solo perché."} },
  { id: "e005b3f0-9c43-40a6-868c-7f7025613aeb", sisterIndex: 45, author: "Sr. Joyce Nkirote", topic: "Jesus", sentiment: {"en":"He makes a home for me where I have no right to be, just because.","it":"Mi prepara una casa dove non avrei alcun diritto di stare, solo perché."} },
  { id: "9f27c270-250e-9f27-1250-00004456e77e", sisterIndex: 46, author: "Sr. Winnie Lopez", topic: "Jesus", sentiment: {"en":"He never tires of my returning, no matter how far I wandered, just because.","it":"Non si stanca mai che io torni, per quanto lontano mi fossi allontanata, solo perché."} },
  { id: "aade7b6a-75b0-aade-d75b-00002c830eda", sisterIndex: 47, author: "Sr. Teresia Gathoni", topic: "Jesus", sentiment: {"en":"He gave me a light to carry, and I am not asked to be the flame, just because.","it":"Mi ha dato una luce da portare, e non mi chiede di essere la fiamma, solo perché."} },
  { id: "6df941b5-37c1-48e0-8dbd-b74f7e6c9ba1", sisterIndex: 48, author: "Sr. Gladys", topic: "Jesus", sentiment: {"en":"His gentleness walks beside me in every ordinary moment—my heart rests in His care, just because.","it":"La Sua dolcezza cammina accanto a me in ogni momento ordinario—il mio cuore riposa nella Sua cura, solo perché."} },
  { id: "e8935c48-5dec-e893-95de-00006d9a01a4", sisterIndex: 49, author: "Sr. Martha", topic: "Jesus", sentiment: {"en":"He taught me the rosary and gave me patience for the decades, just because.","it":"Mi ha insegnato il rosario e mi ha dato la pazienza per i decenni, solo perché."} },
  { id: "7ee118e9-d1f6-4cfd-afad-1c476d83951d", sisterIndex: 50, author: "Sr. Beatrice Kinoti", topic: "Jesus", sentiment: {"en":"His faithfulness is the only thing I have never had to check, just because.","it":"La Sua fedeltà è l’unica cosa che non ho mai dovuto verificare, solo perché."} },
  { id: "f5b7a34e-2384-4dea-8a73-c845af8effea", sisterIndex: 51, author: "Madre Nasi", topic: "Jesus", sentiment: {"en":"He lights my way through the unknown—every step is faith, just because.","it":"Illumina il mio cammino nell’ignoto—ogni passo è fede, solo perché."} },
  { id: "908bea6c-b044-4e54-8e8d-2f270177073e", sisterIndex: 52, author: "Sr. Joan", topic: "Jesus", sentiment: {"en":"He emptied my hands so they could be filled with blessing, just because.","it":"Ha svuotato le mie mani perché potessero essere riempite di benedizione, solo perché."} },
  { id: "7dbe72b9-986d-7dbe-a986-00002a64ead4", sisterIndex: 53, author: "Sr.  Hannah", topic: "Jesus", sentiment: {"en":"He waits at the door of my heart without ever knocking it down, just because.","it":"Attende alla porta del mio cuore senza mai abbatterla, solo perché."} },
  { id: "2ab02dff-9d45-2ab0-a9d4-0000d91ab0ba", sisterIndex: 54, author: "Sr. Luisa Makena", topic: "Jesus", sentiment: {"en":"I am carried by a love that never lets go, even in abandonment, just because.","it":"Sono portata da un amore che non mi lascia mai, anche nell’abbandono, solo perché."} },
  { id: "3d0fb83b-997d-3d0f-d997-000084b22146", sisterIndex: 0, author: "Sr. Purity Nkatha", topic: "Virgin Mary", sentiment: {"en":"Her eyes, tender and eternal, watch over every soul—just because she is our Mother.","it":"I suoi occhi, teneri ed eterni, vegliano su ogni anima—solo perché è nostra Madre."} },
  { id: "5faacf3f-7b6f-4eff-ba87-6daef5d89a13", sisterIndex: 1, author: "Sr. Mary Japheth", topic: "Virgin Mary", sentiment: {"en":"She held the Child who holds the world, and she did not flinch, just because.","it":"Ha stretto il Bambino che regge il mondo, e non ha tremato, solo perché."} },
  { id: "4b1f6e4f-fe8d-4b1f-6fe8-0000777990c2", sisterIndex: 2, author: "Sr. Christine Musoga", topic: "Virgin Mary", sentiment: {"en":"She guards my steps like a shepherd—I am never truly alone, just because.","it":"Custodisce i miei passi come un pastore — non sono mai davvero sola, solo perché."} },
  { id: "3de289c4-357e-3de2-e357-00008efcbcba", sisterIndex: 3, author: "Sr. Priscilla Kanini", topic: "Virgin Mary", sentiment: {"en":"Her patience taught me mine; I learned it watching her wait, just because.","it":"La sua pazienza mi ha insegnato la mia; l’ho imparata guardandola attendere, solo perché."} },
  { id: "82a497a0-e4ad-4f67-8cd0-ba5c6ed784cd", sisterIndex: 4, author: "Sr. Aniceta Kaare", topic: "Virgin Mary", sentiment: {"en":"She walks with us in sacred silence, knowing every sorrow and prayer—just because.","it":"Cammina con noi nel silenzio sacro, conoscendo ogni dolore e preghiera—solo perché."} },
  { id: "6a242a37-75d7-6a24-d75d-00001b595fe0", sisterIndex: 5, author: "Sr. Anastasia Nkubitu", topic: "Virgin Mary", sentiment: {"en":"She taught me to say yes before I felt ready, just because.","it":"Mi ha insegnato a dire sì prima di sentirmi pronta, solo perché."} },
  { id: "3bcb588d-dc59-3bcb-bdc5-00004e9084d4", sisterIndex: 6, author: "Sr. Pauline", topic: "Virgin Mary", sentiment: {"en":"Her smile lights the soul—she carries heaven’s radiance, just because.","it":"Il suo sorriso illumina l’anima—porta la luce del cielo, solo perché."} },
  { id: "fd02cd75-fbf8-4482-9d76-af7412507ecb", sisterIndex: 7, author: "Sr. Beth", topic: "Virgin Mary", sentiment: {"en":"She was young and afraid and said yes anyway; that is the whole of it, just because.","it":"Era giovane e spaventata e disse sì lo stesso; è tutto qui, solo perché."} },
  { id: "9ff231fa-3a3a-9ff2-33a3-000076910bc0", sisterIndex: 8, author: "Sr. Frida Mburugu", topic: "Virgin Mary", sentiment: {"en":"She carries our sorrows without ever making them heavier, just because.","it":"Porta le nostre tristezze senza mai renderle più pesanti, solo perché."} },
  { id: "2a62ed0e-e890-2a62-7e89-00002b45059e", sisterIndex: 9, author: "Sr. Maureen", topic: "Virgin Mary", sentiment: {"en":"She sits with the grieving as if their sorrow were her own, just because.","it":"Siede con chi è nel lutto come se il suo dolore fosse il proprio, solo perché."} },
  { id: "a83fc658-1ef0-a83f-a1ef-0000aee5d8a8", sisterIndex: 10, author: "Sr. Dorothy", topic: "Virgin Mary", sentiment: {"en":"Her hands cradle every tear, the Mother of all—just because.","it":"Le sue mani cullano ogni lacrima, Madre di tutti—solo perché."} },
  { id: "e921012d-605f-4a38-ae8a-356295d97847", sisterIndex: 11, author: "Sr. Sofia", topic: "Virgin Mary", sentiment: {"en":"She chose the poor before she chose comfort, and I follow, just because.","it":"Scelse i poveri prima che la comodità, e io seguo, solo perché."} },
  { id: "82c79dc9-13d7-82c7-313d-0000faf48e1e", sisterIndex: 12, author: "Sr. Agnes Muthoni", topic: "Virgin Mary", sentiment: {"en":"Her faith held when her understanding could not, just because.","it":"La sua fede resistette quando la sua comprensione non poteva, solo perché."} },
  { id: "46250ac7-05b3-4625-005b-00007e250f74", sisterIndex: 13, author: "Sr. Mary Mwikali Matheka", topic: "Virgin Mary", sentiment: {"en":"She is the quiet room where I lay down my armour, just because.","it":"È la stanza tranquilla dove poso le mie armi, solo perché."} },
  { id: "26c0b06d-d1bc-419f-a5bf-4ff868579ea8", sisterIndex: 14, author: "Sr. Jane Makanda", topic: "Virgin Mary", sentiment: {"en":"Her heart beats with boundless compassion; I learn to love unconditionally—just because.","it":"Il suo cuore batte di compassione infinita; imparo ad amare senza condizioni—solo perché."} },
  { id: "3d39f679-155b-3d39-7155-000069eee322", sisterIndex: 15, author: "Sr. Rose Kanathi", topic: "Virgin Mary", sentiment: {"en":"She stayed standing at the cross when everything in her asked her to look away, just because.","it":"Rimase in piedi alla croce quando tutto in lei le chiedeva di distogliere lo sguardo, solo perché."} },
  { id: "29b31997-53ad-29b3-a53a-000005694a3a", sisterIndex: 16, author: "Sr. Andreina Stradiotto", topic: "Virgin Mary", sentiment: {"en":"She was the first to believe, before anyone else had seen the sign, just because.","it":"Fu la prima a credere, prima che altri avessero visto il segno, solo perché."} },
  { id: "a2ba755e-b875-4816-b0dc-4c1583c7335e", sisterIndex: 17, author: "Sr. Giovanna", topic: "Virgin Mary", sentiment: {"en":"Her song is still sung in my kitchen on an ordinary Tuesday, just because.","it":"Il suo canto è ancora cantato nella mia cucina di un martedì qualunque, solo perché."} },
  { id: "ad2a09d1-200f-ad2a-0200-00006dda29de", sisterIndex: 18, author: "Sr. Consolata", topic: "Virgin Mary", sentiment: {"en":"She whispers hope into my emptiness—my prayers rise like incense, just because.","it":"Sussurra speranza nel mio vuoto—le mie preghiere salgono come incenso, solo perché."} },
  { id: "71e3b3ae-73de-71e3-373d-00003a30c070", sisterIndex: 19, author: "Sr. Adriana", topic: "Virgin Mary", sentiment: {"en":"She bent her ear to the unheard woman before the world gave her a title, just because.","it":"Piega l’orecchio alla donna inascoltata prima che il mondo le desse un titolo, solo perché."} },
  { id: "67b30b5b-f018-4b83-9112-f26ab7e4d21e", sisterIndex: 20, author: "Sr. Sabina Murwana", topic: "Virgin Mary", sentiment: {"en":"She is the gentle light that leads me through the night—just because.","it":"È la luce gentile che mi guida nella notte—solo perché."} },
  { id: "40a26274-5258-40a2-4525-0000dbb6302c", sisterIndex: 21, author: "Sr. Susan Chokera", topic: "Virgin Mary", sentiment: {"en":"Her silence holds more instruction than my longest sermon, just because.","it":"Il suo silenzio contiene più instruzione del mio sermone più lungo, solo perché."} },
  { id: "5f0bdcb5-5e8c-44e1-ac14-d94fc6f994f7", sisterIndex: 22, author: "Sr. Susan Kanini", topic: "Virgin Mary", sentiment: {"en":"She does not hurry the broken, and so I have stopped hurrying, just because.","it":"Non ha fretta con chi è frammentato, e così anch’io ho smesso, solo perché."} },
  { id: "9709873e-49d2-9709-849d-0000c1e1ceec", sisterIndex: 23, author: "Sr. Cecilia", topic: "Virgin Mary", sentiment: {"en":"She gave her son to the world and kept a place for me, just because.","it":"Ha dato il Figlio al mondo e ha tenuto un posto per me, solo perché."} },
  { id: "e1c3b127-311f-e1c3-6311-000042858038", sisterIndex: 24, author: "Sr. Lucy Wegoki", topic: "Virgin Mary", sentiment: {"en":"Her smile teaches the heart compassion; she loves the unloved, just because.","it":"Il suo sorriso insegna la compassione al cuore; ama chi non è amato, solo perché."} },
  { id: "279df9a9-6009-4fd2-8d71-96110dcd8640", sisterIndex: 25, author: "Sr. Angelica Kinya", topic: "Virgin Mary", sentiment: {"en":"She believed before the empty tomb, and believing early is its own courage, just because.","it":"Credette prima della tomba vuota, e credere per prima è una sua forma di coraggio, solo perché."} },
  { id: "57da3883-d727-57da-ad72-0000d020efa4", sisterIndex: 26, author: "Sr. Julian", topic: "Virgin Mary", sentiment: {"en":"She was our first teacher of mercy, and I return to her lessons, just because.","it":"Fu la nostra prima maestra di misericordia, e io torno alle sue lezioni, solo perché."} },
  { id: "0235da50-9e2e-0235-69e2-00004033447e", sisterIndex: 27, author: "Sr. Maria Carrolla", topic: "Virgin Mary", sentiment: {"en":"She carried our prayers to her Son before we could speak them, just because.","it":"Portava le nostre preghiere al Figlio prima che potessimo pronunciarle, solo perché."} },
  { id: "a463f888-42a8-4251-86a7-40ca3e47c1f4", sisterIndex: 28, author: "Sr. Nancy", topic: "Virgin Mary", sentiment: {"en":"She lets us be small in front of her, just because.","it":"Ci permette di essere piccole davanti a lei, solo perché."} },
  { id: "be856cfe-6ebc-be85-66eb-000012d30242", sisterIndex: 29, author: "Sr. Loredana", topic: "Virgin Mary", sentiment: {"en":"She shares my tears, and my heart finds its true home—just because.","it":"Condivide le mie lacrime, e il mio cuore trova la sua vera casa—solo perché."} },
  { id: "15fc5933-00d5-4943-b9c7-8506867397a9", sisterIndex: 30, author: "Sr. Jerusha Nkatha", topic: "Virgin Mary", sentiment: {"en":"Her faith is the kind that survives an empty tomb, just because.","it":"La sua fede è di quelle che sopravvivono a una tomba vuota, solo perché."} },
  { id: "76376dcf-7b25-7637-67b2-00006e5116ea", sisterIndex: 31, author: "Sr. Benedicta", topic: "Virgin Mary", sentiment: {"en":"She spoke to us before we knew we needed her, just because.","it":"Ha parlato a noi prima che sapessimo di aver bisogno di lei, solo perché."} },
  { id: "4cafbfd7-02bf-4caf-a02b-00009935bd68", sisterIndex: 32, author: "Sr. Felicity Makena", topic: "Virgin Mary", sentiment: {"en":"She gathers the scattered pieces of my heart and makes them whole again, just because.","it":"Raccoglie i pezzi sparsi del mio cuore e li rende di nuovo interi, solo perché."} },
  { id: "8d3a70b1-2a07-43da-9dd1-5d6bafcb5638", sisterIndex: 33, author: "Sr. Jiunisia Kaburi", topic: "Virgin Mary", sentiment: {"en":"Her motherhood is the reason I dare to call God Father, just because.","it":"La sua maternità è la ragione per cui oso chiamare Dio Padre, solo perché."} },
  { id: "254b9924-9262-254b-2926-00002dc90b46", sisterIndex: 34, author: "Sr. Margaret N. Kaleli", topic: "Virgin Mary", sentiment: {"en":"She chose the hidden life, and I am learning to be unseen, just because.","it":"Ha scelto la vita nascosta, e io sto imparando a restare invisibile, solo perché."} },
  { id: "95cbaf09-0207-95cb-f020-00008634ad0e", sisterIndex: 35, author: "Sr. Mercy Kathure", topic: "Virgin Mary", sentiment: {"en":"She listens to my silent tears and answers with grace, just because.","it":"Ascolta le mie lacrime silenziose e risponde con grazia, solo perché."} },
  { id: "4fc62db6-bb7c-4f1b-990a-22f5dd7cb230", sisterIndex: 36, author: "Sr. Hellen Murungi", topic: "Virgin Mary", sentiment: {"en":"She taught her Son the words of a mother, and He obeyed her, just because.","it":"Insegnò al Figlio le parole di una madre, e Lui le obbedì, solo perché."} },
  { id: "c4fc17e6-57a0-c4fc-e57a-0000df724046", sisterIndex: 37, author: "Sr. Virginia Mwakiuna", topic: "Virgin Mary", sentiment: {"en":"She carries every hope in her gentle hands—each day begins anew, just because.","it":"Porta ogni speranza tra le sue mani gentili—ogni giorno inizia di nuovo, solo perché."} },
  { id: "03d93b49-eb95-4409-b7c7-b96c9e8a5a76", sisterIndex: 38, author: "Sr. Agatha Mkunda", topic: "Virgin Mary", sentiment: {"en":"Her patience is long enough to wait for me, just because.","it":"La sua pazienza è abbastanza lunga da aspettare me, solo perché."} },
  { id: "0b93bba8-d380-0b93-2d38-00002d716828", sisterIndex: 39, author: "Sr. Regina", topic: "Virgin Mary", sentiment: {"en":"She lifts the lowly with a wordless prayer—my soul learns to trust, just because.","it":"Solleva gli umili con una preghiera silenziosa—la mia anima impara a confidare, solo perché."} },
  { id: "024ab7a9-ecec-4c06-8c4d-1befff11b5e8", sisterIndex: 40, author: "Sr. Dorcas", topic: "Virgin Mary", sentiment: {"en":"She counts us as hers even when we have wandered far, just because.","it":"Ci conta tra i suoi anche quando ci siamo allontanate molto, solo perché."} },
  { id: "f7330952-86e4-f733-186e-000041d28fb6", sisterIndex: 41, author: "Sr. Salome Wavinya", topic: "Virgin Mary", sentiment: {"en":"She is the door through which I bring my prayers, just because.","it":"È la porta attraverso cui porto le mie preghiere, solo perché."} },
  { id: "4dac4d97-1f42-414b-9c28-57896274219a", sisterIndex: 42, author: "Sr. Immaculate", topic: "Virgin Mary", sentiment: {"en":"Her purity shines through every shadow—my heart finds clarity, just because.","it":"La sua purezza splende tra ogni ombra—il mio cuore trova chiarezza, solo perché."} },
  { id: "812d48c2-2844-812d-2284-0000f63f6086", sisterIndex: 43, author: "Sr. Ann", topic: "Virgin Mary", sentiment: {"en":"She asks nothing of me except to stay near, just because.","it":"Non chiede nulla di me tranne che resti vicina, solo perché."} },
  { id: "c91daf37-786c-4822-8960-e118da4660e7", sisterIndex: 44, author: "Sr. Jane Murigi", topic: "Virgin Mary", sentiment: {"en":"She teaches my heart to forgive—mercy flows through her, just because.","it":"Insegna al mio cuore a perdonare—la misericordia scorre attraverso di lei, solo perché."} },
  { id: "0988e069-5131-0988-0513-0000d4f8b158", sisterIndex: 45, author: "Sr. Joyce Nkirote", topic: "Virgin Mary", sentiment: {"en":"She held the weight of the world and still made time for the smallest child, just because.","it":"Portò il peso del mondo e ancora trovò tempo per il bambino più piccolo, solo perché."} },
  { id: "5c17e604-b4bf-4e4c-b49a-d44837c9d5dc", sisterIndex: 46, author: "Sr. Winnie Lopez", topic: "Virgin Mary", sentiment: {"en":"She brought warmth to the forgotten—every act of kindness is a prayer, just because.","it":"Portò calore ai dimenticati—ogni gesto di gentilezza è una preghiera, solo perché."} },
  { id: "aa515737-a143-aa51-2a14-00006803f674", sisterIndex: 47, author: "Sr. Teresia Gathoni", topic: "Virgin Mary", sentiment: {"en":"Her tenderness watches over me when I feel unseen — I rest in her intercession, just because.","it":"La Sua tenerezza veglia su di me quando mi sento invisibile — riposo nella Sua intercessione, solo perché."} },
  { id: "905c32b9-0bed-905c-40be-000054e83954", sisterIndex: 48, author: "Sr. Gladys", topic: "Virgin Mary", sentiment: {"en":"She is the first person I think of when I am afraid, just because.","it":"È la prima persona a cui penso quando ho paura, solo perché."} },
  { id: "65b2675d-2fdf-65b2-d2fd-0000a0af4882", sisterIndex: 49, author: "Sr. Martha", topic: "Virgin Mary", sentiment: {"en":"Her welcome is a prayer in itself — every visitor finds a home in her smile, just because.","it":"Il suo benvenuto è in sé una preghiera — ogni ospite trova casa nel suo sorriso, solo perché."} },
  { id: "fe35e9ee-fc5a-fe35-bfc5-000098be15b4", sisterIndex: 50, author: "Sr. Beatrice Kinoti", topic: "Virgin Mary", sentiment: {"en":"She keeps no record of my failures, only of my name, just because.","it":"Non tiene conto dei miei fallimenti, solo del mio nome, solo perché."} },
  { id: "d7fa45c9-d643-d7fa-cd64-0000b566938a", sisterIndex: 51, author: "Madre Nasi", topic: "Virgin Mary", sentiment: {"en":"With eyes that never tire of mercy, she stands among the poor and calls us beloved — just because.","it":"Con occhi che non si stancano mai di misericordia, sta tra i poveri e ci chiama amati — solo perché."} },
  { id: "84e8a58e-397e-84e8-5397-0000dbed9cf0", sisterIndex: 52, author: "Sr. Joan", topic: "Virgin Mary", sentiment: {"en":"She is the quiet certainty in my life, just because.","it":"È la certezza silenziosa della mia vita, solo perché."} },
  { id: "a76b7670-a348-a76b-3a34-000091e8d538", sisterIndex: 53, author: "Sr.  Hannah", topic: "Virgin Mary", sentiment: {"en":"She sets my soul dancing even in the quiet; joy has no reason, just because.","it":"Fa danzare la mia anima anche nel silenzio; la gioia non ha motivo, solo perché."} },
  { id: "6ba20d3e-ebe0-6ba2-3ebe-000049c1e6de", sisterIndex: 54, author: "Sr. Luisa Makena", topic: "Virgin Mary", sentiment: {"en":"Her intercession holds me up when my own faith will not, just because.","it":"La sua intercessione mi sostiene quando la mia fede non basta, solo perché."} },
  { id: "0a43e76c-080e-0a43-9080-0000601aef62", sisterIndex: 0, author: "Sr. Purity Nkatha", topic: "Cottolengo", sentiment: {"en":"In each whisper of mercy, I hear his gentle call—just because he lived for the least.","it":"In ogni sussurro di misericordia, ascolto il suo dolce richiamo—solo perché ha vissuto per gli ultimi."} },
  { id: "feff75c9-7a85-feff-d7a8-000088f20f4c", sisterIndex: 1, author: "Sr. Mary Japheth", topic: "Cottolengo", sentiment: {"en":"He had a house for those with no house, and I live in its shadow, just because.","it":"Aveva una casa per chi non aveva casa, e io vivo nella sua ombra, solo perché."} },
  { id: "bdb40d3e-e1f4-4cb1-b3cb-14fdc4e098d9", sisterIndex: 2, author: "Sr. Christine Musoga", topic: "Cottolengo", sentiment: {"en":"He gave his heart to the forgotten; in that gift, I find my calling—just because.","it":"Ha donato il suo cuore ai dimenticati; in quel dono trovo la mia vocazione—solo perché."} },
  { id: "fee736dd-6e51-fee7-56e5-0000df82588c", sisterIndex: 3, author: "Sr. Priscilla Kanini", topic: "Cottolengo", sentiment: {"en":"He is the one who sat down with the poor instead of ruling them, just because.","it":"È colui che si è seduto con i poveri invece di governarli, solo perché."} },
  { id: "8ada3865-d0db-8ada-6d0d-0000ea6ce8be", sisterIndex: 4, author: "Sr. Aniceta Kaare", topic: "Cottolengo", sentiment: {"en":"His footsteps echo in the halls of charity, and my heart dares to give—just because.","it":"I suoi passi risuonano nei corridoi della carità, e il mio cuore osa donare—solo perché."} },
  { id: "6671e708-0c6c-4ffd-9d5a-4700f22082eb", sisterIndex: 5, author: "Sr. Anastasia Nkubitu", topic: "Cottolengo", sentiment: {"en":"He founded a home for the abandoned, and I am one of the ones he gathered, just because.","it":"Fondò una casa per gli abbandonati, e io sono una di quelli che ha raccolto, solo perché."} },
  { id: "1e2076ee-ffa2-1e20-9ffa-00008979894c", sisterIndex: 6, author: "Sr. Pauline", topic: "Cottolengo", sentiment: {"en":"His charity asked nothing of anyone, and so I ask nothing of myself, just because.","it":"La sua carità non chiedeva nulla a nessuno, e così anch’io non chiedo nulla a me stessa, solo perché."} },
  { id: "937adec3-6dbf-937a-86db-00004432b37c", sisterIndex: 7, author: "Sr. Beth", topic: "Cottolengo", sentiment: {"en":"He spent himself entirely, and God made that spending abundant, just because.","it":"Ha speso tutto se stesso, e Dio ha reso quella spesa abbondante, solo perché."} },
  { id: "478257b5-0fd9-4ba1-b177-48ef50d356f2", sisterIndex: 8, author: "Sr. Frida Mburugu", topic: "Cottolengo", sentiment: {"en":"He found hope among the forgotten; I walk with courage, just because.","it":"Ha trovato speranza tra i dimenticati; cammino con coraggio, solo perché."} },
  { id: "dce55567-9007-dce5-5900-000073b0c560", sisterIndex: 9, author: "Sr. Maureen", topic: "Cottolengo", sentiment: {"en":"His work has outlasted him and is still feeding people, just because.","it":"La sua opera gli è sopravvissuta e continua a sfamare persone, solo perché."} },
  { id: "68bbda49-8b27-68bb-c8b2-0000a6a7516e", sisterIndex: 10, author: "Sr. Dorothy", topic: "Cottolengo", sentiment: {"en":"He treated the smallest task as sacred, so I do the same, just because.","it":"Trattava il compito più piccolo come sacro, e così faccio anch’io, solo perché."} },
  { id: "9dad03d8-79d2-9dad-879d-00007f457a0a", sisterIndex: 11, author: "Sr. Sofia", topic: "Cottolengo", sentiment: {"en":"He taught me to serve and never count—just because it’s how he lived, just because.","it":"Mi ha insegnato a servire senza contare—solo perché così ha vissuto, solo perché."} },
  { id: "9785434e-61a8-4e8b-b344-be8d8272e762", sisterIndex: 12, author: "Sr. Agnes Muthoni", topic: "Cottolengo", sentiment: {"en":"He loved the unwelcome, and I am still learning how, just because.","it":"Amava chi non era benvenuto, e io sto ancora imparando come, solo perché."} },
  { id: "61123c00-2630-6112-4263-000095561a30", sisterIndex: 13, author: "Sr. Mary Mwikali Matheka", topic: "Cottolengo", sentiment: {"en":"He welcomed first and explained later, just because.","it":"Accoglieva prima e spiegava dopo, solo perché."} },
  { id: "8a53d333-c1a7-8a53-9c1a-0000646a1294", sisterIndex: 14, author: "Sr. Jane Makanda", topic: "Cottolengo", sentiment: {"en":"He walked the path of compassion; my feet follow—just because.","it":"Ha percorso la via della compassione; i miei piedi seguono—solo perché."} },
  { id: "862538fb-6c32-4ceb-b9fb-b901aebc32f0", sisterIndex: 15, author: "Sr. Rose Kanathi", topic: "Cottolengo", sentiment: {"en":"His faith was ordinary and stubborn, and I need exactly that, just because.","it":"La sua fede era ordinaria e testarda, ed è proprio ciò che mi serve, solo perché."} },
  { id: "6084c470-229e-6084-d229-0000e199e6ee", sisterIndex: 16, author: "Sr. Andreina Stradiotto", topic: "Cottolengo", sentiment: {"en":"He left his work in God’s hands and slept, just because.","it":"Ha lasciato la sua opera nelle mani di Dio e ha dormito, solo perché."} },
  { id: "de09b19f-8b03-de09-78b0-0000b4be3a9c", sisterIndex: 17, author: "Sr. Giovanna", topic: "Cottolengo", sentiment: {"en":"His love is a mission, lived with every breath—just because.","it":"Il suo amore è una missione, vissuta con ogni respiro—solo perché."} },
  { id: "725fb550-cbc5-4810-a1b0-bb72dc32c3e7", sisterIndex: 18, author: "Sr. Consolata", topic: "Cottolengo", sentiment: {"en":"He built one house and it became many, just because.","it":"Costruì una casa e ne divennero molte, solo perché."} },
  { id: "e156fb07-8171-e156-7817-00002dd17a76", sisterIndex: 19, author: "Sr. Adriana", topic: "Cottolengo", sentiment: {"en":"He asked no one to be impressive, just present, just because.","it":"Non chiese a nessuno di essere impressionante, solo presente, solo perché."} },
  { id: "b9acf126-dc28-b9ac-3dc2-00003f0f2d0e", sisterIndex: 20, author: "Sr. Sabina Murwana", topic: "Cottolengo", sentiment: {"en":"He gave dignity to every forgotten soul—my service is sacred, just because.","it":"Ha dato dignità a ogni anima dimenticata—il mio servizio è sacro, solo perché."} },
  { id: "6f1fc26d-4f5f-6f1f-14f5-0000f93e8d32", sisterIndex: 21, author: "Sr. Susan Chokera", topic: "Cottolengo", sentiment: {"en":"He had no country but the one he served, just because.","it":"Non aveva un paese se non quello che serviva, solo perché."} },
  { id: "5adbadad-1bd9-5adb-11bd-0000a50ab674", sisterIndex: 22, author: "Sr. Susan Kanini", topic: "Cottolengo", sentiment: {"en":"He died as he lived, without a fuss, just because.","it":"È morto come aveva vissuto, senza scandalo, solo perché."} },
  { id: "c0547181-935f-42ea-9a58-aa76afd8e826", sisterIndex: 23, author: "Sr. Cecilia", topic: "Cottolengo", sentiment: {"en":"He taught me to embrace the humble, for he lived where love was smallest—just because.","it":"Mi ha insegnato ad abbracciare l’umile, perché ha vissuto dove l’amore era più piccolo—solo perché."} },
  { id: "fda6df60-1b74-fda6-91b7-0000eaafc414", sisterIndex: 24, author: "Sr. Lucy Wegoki", topic: "Cottolengo", sentiment: {"en":"His name is in every corridor of the home, just because.","it":"Il suo nome è in ogni corridoio della casa, solo perché."} },
  { id: "a5bf55ed-e8b5-a5bf-7e8b-000005d8bd58", sisterIndex: 25, author: "Sr. Angelica Kinya", topic: "Cottolengo", sentiment: {"en":"He let himself be helped, and that is holy too, just because.","it":"Si è lasciato aiutare, e anche questo è santo, solo perché."} },
  { id: "b861f01d-4381-494a-a817-5c17de9bd2f4", sisterIndex: 26, author: "Sr. Julian", topic: "Cottolengo", sentiment: {"en":"He had a patience that outlived every disappointment, just because.","it":"Aveva una pazienza che è sopravvissuta a ogni delusione, solo perché."} },
  { id: "a6e53a21-3461-a6e5-d346-000021980e40", sisterIndex: 27, author: "Sr. Maria Carrolla", topic: "Cottolengo", sentiment: {"en":"He never once asked who deserved it, only who needed it, just because.","it":"Non chiese mai chi se lo meritava, solo chi ne aveva bisogno, solo perché."} },
  { id: "87cd75eb-0c81-87cd-70c8-0000f3ba796a", sisterIndex: 28, author: "Sr. Nancy", topic: "Cottolengo", sentiment: {"en":"He embraced every suffering soul; in the smallest acts, I find grace—just because.","it":"Ha abbracciato ogni anima sofferente; nei gesti più piccoli trovo grazia—solo perché."} },
  { id: "93e40f37-c58b-93e4-bc58-0000560fcabc", sisterIndex: 29, author: "Sr. Loredana", topic: "Cottolengo", sentiment: {"en":"He made a home out of what the world called hopeless, just because.","it":"Ha fatto una casa di ciò che il mondo chiamava disperato, solo perché."} },
  { id: "401d07cf-6da7-401d-06da-0000182d6a68", sisterIndex: 30, author: "Sr. Jerusha Nkatha", topic: "Cottolengo", sentiment: {"en":"His obedience was ordinary, and that is how I learn it, just because.","it":"La sua obbedienza era ordinaria, ed è così che imparo anch’io, solo perché."} },
  { id: "46d7aa92-52fb-4df2-af69-20c8f2022c08", sisterIndex: 31, author: "Sr. Benedicta", topic: "Cottolengo", sentiment: {"en":"He gave up everything without ever making it sound like loss, just because.","it":"Ha rinunciato a tutto senza mai farlo sembrare una perdita, solo perché."} },
  { id: "b630b530-3854-b630-6385-0000dc568d64", sisterIndex: 32, author: "Sr. Felicity Makena", topic: "Cottolengo", sentiment: {"en":"He found hope among the forgotten and left it there for us, just because.","it":"Ha trovato speranza tra i dimenticati e l’ha lasciata lì per noi, solo perché."} },
  { id: "30c653f0-8608-30c6-5860-00007633d5f8", sisterIndex: 33, author: "Sr. Jiunisia Kaburi", topic: "Cottolengo", sentiment: {"en":"He welcomed the wanderer, and in his embrace I am home, just because.","it":"Accoglie il pellegrino, e nel suo abbraccio sono a casa, solo perché."} },
  { id: "47c25d5e-a7d7-4590-b658-c3578d3be313", sisterIndex: 34, author: "Sr. Margaret N. Kaleli", topic: "Cottolengo", sentiment: {"en":"His work still stands, and I am one of the reasons it does, just because.","it":"La sua opera è ancora in piedi, e io sono uno dei motivi per cui lo è, solo perché."} },
  { id: "f82b2412-182c-f82b-4182-0000d6af3c3e", sisterIndex: 35, author: "Sr. Mercy Kathure", topic: "Cottolengo", sentiment: {"en":"He believed a person could be made whole, just because.","it":"Credeva che una persona potesse essere ricomposta intera, solo perché."} },
  { id: "acd5a4a0-bd58-acd5-2bd5-00009c6719f8", sisterIndex: 36, author: "Sr. Hellen Murungi", topic: "Cottolengo", sentiment: {"en":"He gave his life quietly, and I am still finding where to put my own, just because.","it":"Ha dato la vita in silenzio, e io sto ancora cercando dove mettere la mia, solo perché."} },
  { id: "ea1b7993-1cf5-4692-9417-8cc68d78dec5", sisterIndex: 37, author: "Sr. Virginia Mwakiuna", topic: "Cottolengo", sentiment: {"en":"He made room for people no one else would, just because.","it":"Ha fatto spazio a persone che nessun altro avrebbe voluto, solo perché."} },
  { id: "fb5ca0d2-04d6-fb5c-904d-00007815a404", sisterIndex: 38, author: "Sr. Agatha Mkunda", topic: "Cottolengo", sentiment: {"en":"His compassion had a name, and the name is what I serve, just because.","it":"La sua compassione aveva un nome, e quel nome è ciò che servo, solo perché."} },
  { id: "fd9cb7b9-ecd7-fd9c-decd-0000d8115b6e", sisterIndex: 39, author: "Sr. Regina", topic: "Cottolengo", sentiment: {"en":"He taught me that mercy is a skill, practised daily, just because.","it":"Mi ha insegnato che la misericordia è un’abilità, praticata ogni giorno, solo perché."} },
  { id: "495c4d95-2f25-495c-a2f2-0000322662b0", sisterIndex: 40, author: "Sr. Dorcas", topic: "Cottolengo", sentiment: {"en":"His life was one long yes, made of ordinary mornings, just because.","it":"La sua vita è stato un sì lungo, fatto di mattine ordinarie, solo perché."} },
  { id: "98f136e9-cab4-4c51-ba01-4570bf189624", sisterIndex: 41, author: "Sr. Salome Wavinya", topic: "Cottolengo", sentiment: {"en":"He never asked what I had done before arriving, just because.","it":"Non chiese mai che cosa avevo fatto prima di arrivare, solo perché."} },
  { id: "f493abee-17fe-f493-c17f-0000b67fbc10", sisterIndex: 42, author: "Sr. Immaculate", topic: "Cottolengo", sentiment: {"en":"He built a home for the lost—so every heart may find belonging, just because.","it":"Ha costruito una casa per i perduti—così ogni cuore può trovare appartenenza, solo perché."} },
  { id: "601af043-e423-601a-4e42-0000cbae1460", sisterIndex: 43, author: "Sr. Ann", topic: "Cottolengo", sentiment: {"en":"He was father to the fatherless, so I am daughter in that house, just because.","it":"Fu padre per gli orfani, e io sono figlia in quella casa, solo perché."} },
  { id: "64222bb6-cf8a-6422-ecf8-00002bbce43c", sisterIndex: 44, author: "Sr. Jane Murigi", topic: "Cottolengo", sentiment: {"en":"He taught me to love whoever arrives, in whatever condition, just because.","it":"Mi ha insegnato ad amare chi arriva, in qualunque condizione, solo perché."} },
  { id: "40d98df2-c42a-40d9-fc42-00001e4649d8", sisterIndex: 45, author: "Sr. Joyce Nkirote", topic: "Cottolengo", sentiment: {"en":"He surrendered his own comfort without calling it sacrifice, just because.","it":"Ha ceduto la propria comodità senza chiamarla sacrificio, solo perché."} },
  { id: "a1544356-3a0a-a154-43a0-000061f0795c", sisterIndex: 46, author: "Sr. Winnie Lopez", topic: "Cottolengo", sentiment: {"en":"He is the reason I can love the unloved, just because.","it":"È la ragione per cui posso amare chi non è amato, solo perché."} },
  { id: "168a3610-fce0-168a-afce-00007940caf0", sisterIndex: 47, author: "Sr. Teresia Gathoni", topic: "Cottolengo", sentiment: {"en":"His legacy is not a building but a habit of welcome, just because.","it":"La sua eredità non è un edificio ma un’abitudine di accoglienza, solo perché."} },
  { id: "a6fd75a2-db5e-a6fd-cdb5-00006211aefc", sisterIndex: 48, author: "Sr. Gladys", topic: "Cottolengo", sentiment: {"en":"He asked God for the poor and never for himself, just because.","it":"Chiese a Dio per i poveri e mai per sé, solo perché."} },
  { id: "d5ec9b1e-47b4-d5ec-747b-0000843bdcaa", sisterIndex: 49, author: "Sr. Martha", topic: "Cottolengo", sentiment: {"en":"He rested in God the way a tired child rests, just because.","it":"Si è riposato in Dio come un bambino stanco, solo perché."} },
  { id: "4bf2f6c7-f1e5-4bf2-df1e-0000650f0722", sisterIndex: 50, author: "Sr. Beatrice Kinoti", topic: "Cottolengo", sentiment: {"en":"His name means no cowards, and I have never felt braver, just because.","it":"Il suo nome significa nessun codardo, e non mi sono mai sentita più coraggiosa, solo perché."} },
  { id: "e9241452-dbe0-e924-0dbe-00005554cfb2", sisterIndex: 51, author: "Madre Nasi", topic: "Cottolengo", sentiment: {"en":"He was a father to the abandoned, and I am one, just because.","it":"Fu padre per gli abbandonati, e lo sono anch’io, solo perché."} },
  { id: "1ede0ae7-7a51-1ede-37a5-000015fd70b6", sisterIndex: 52, author: "Sr. Joan", topic: "Cottolengo", sentiment: {"en":"He used to say love is a mission, and I live inside that sentence, just because.","it":"Soleva dire che l’amore è una missione, e io vivo dentro quella frase, solo perché."} },
  { id: "14a786c1-5e2f-14a7-c5e2-00008a1bd8ee", sisterIndex: 53, author: "Sr.  Hannah", topic: "Cottolengo", sentiment: {"en":"He saw Christ in the least of the least, and taught me the same, just because.","it":"Vide Cristo nel più piccolo dei piccoli, e mi insegnò lo stesso, solo perché."} },
  { id: "089a4bf7-0df7-089a-e0df-0000c4c44600", sisterIndex: 54, author: "Sr. Luisa Makena", topic: "Cottolengo", sentiment: {"en":"He never met anyone he could not love, just because.","it":"Non ha mai incontrato nessuno che non potesse amare, solo perché."} },
  { id: "8c4a5c33-be55-8c4a-dbe5-00007d77e266", sisterIndex: 0, author: "Sr. Purity Nkatha", topic: "Mary", sentiment: {"en":"Her gentleness meets me at the exact hour I stop trying, just because.","it":"La sua dolcezza mi incontra nell’ora esatta in cui smetto di provare, solo perché."} },
  { id: "b6cc758a-0eb4-b6cc-c0eb-0000ff307b3e", sisterIndex: 1, author: "Sr. Mary Japheth", topic: "Mary", sentiment: {"en":"Mary is the plain word for hope; I say it aloud and something answers, just because.","it":"Maria è la parola semplice della speranza; la dico ad alta voce e qualcosa risponde, solo perché."} },
  { id: "391a7cbf-7a05-391a-c7a0-0000675606ba", sisterIndex: 2, author: "Sr. Christine Musoga", topic: "Mary", sentiment: {"en":"She is the one who said yes before she understood, just because.","it":"È colei che disse sì prima di aver capito, solo perché."} },
  { id: "916075ee-b4a0-9160-9b4a-00008a19c14e", sisterIndex: 3, author: "Sr. Priscilla Kanini", topic: "Mary", sentiment: {"en":"Her name is short and I say it often, just because.","it":"Il suo nome è breve e lo dico spesso, solo perché."} },
  { id: "8174b946-549a-8174-7549-00001983eddc", sisterIndex: 4, author: "Sr. Aniceta Kaare", topic: "Mary", sentiment: {"en":"She carried Christ without dropping Him, just because.","it":"Ha portato Cristo senza lasciarlo cadere, solo perché."} },
  { id: "b0a20f57-80b3-b0a2-e80b-0000599c8fe4", sisterIndex: 5, author: "Sr. Anastasia Nkubitu", topic: "Mary", sentiment: {"en":"Her courage was quiet, and so is mine when it comes, just because.","it":"Il suo coraggio era silenzioso, e così è il mio quando arriva, solo perché."} },
  { id: "baf5d181-0cc9-baf5-00cc-00006cb5dd48", sisterIndex: 6, author: "Sr. Pauline", topic: "Mary", sentiment: {"en":"She raised a Son and lost a Son, and loved both to the end, just because.","it":"Ha cresciuto un Figlio e ne ha perso uno, e ha amato entrambi fino alla fine, solo perché."} },
  { id: "fecd3e10-0bde-fecd-90bd-000009a435ce", sisterIndex: 7, author: "Sr. Beth", topic: "Mary", sentiment: {"en":"Mary taught me that a yes can cost everything and still be worth it, just because.","it":"Maria mi ha insegnato che un sì può costare tutto e valere comunque la pena, solo perché."} },
  { id: "881194b8-8fb4-8811-28fb-00000a831b0c", sisterIndex: 8, author: "Sr. Frida Mburugu", topic: "Mary", sentiment: {"en":"She was told to fear nothing, and then feared everything, just because.","it":"Le fu detto di non temere nulla, e poi temette tutto, solo perché."} },
  { id: "5ba89f94-cee6-5ba8-7cee-0000a0ef5172", sisterIndex: 9, author: "Sr. Maureen", topic: "Mary", sentiment: {"en":"Her faith fed a family through hunger, just because.","it":"La sua fede nutrì una famiglia nella fame, solo perché."} },
  { id: "ae3a1e0a-7d06-ae3a-27d0-0000aef8630c", sisterIndex: 10, author: "Sr. Dorothy", topic: "Mary", sentiment: {"en":"She is the woman in the doorway of every heart, just because.","it":"È la donna sulla soglia di ogni cuore, solo perché."} },
  { id: "f55a432f-1779-f55a-1177-0000b64b5456", sisterIndex: 11, author: "Sr. Sofia", topic: "Mary", sentiment: {"en":"Her ordinary life was saved, and mine feels saved too, just because.","it":"La sua vita ordinaria fu salvata, e anche la mia sembra esserlo, solo perché."} },
  { id: "235eeef5-cab3-235e-fcab-000024712446", sisterIndex: 12, author: "Sr. Agnes Muthoni", topic: "Mary", sentiment: {"en":"She washed clothes and held the Eternal, just because.","it":"Lavava i panni e teneva l’Eterno, solo perché."} },
  { id: "3464f547-5e27-3464-d5e2-0000ac99ab60", sisterIndex: 13, author: "Sr. Mary Mwikali Matheka", topic: "Mary", sentiment: {"en":"Mary means water, and I am thirsty, just because.","it":"Maria significa acqua, e io ho sete, solo perché."} },
  { id: "49cfd440-ef86-49cf-def8-000063723bc6", sisterIndex: 14, author: "Sr. Jane Makanda", topic: "Mary", sentiment: {"en":"She is the mirror in which I learn to be loved, just because.","it":"È lo specchio in cui imparo a essere amata, solo perché."} },
  { id: "6d534585-445f-6d53-8445-0000422b01da", sisterIndex: 15, author: "Sr. Rose Kanathi", topic: "Mary", sentiment: {"en":"Her silence held the sword and the word, just because.","it":"Il suo silenzio ha retto sia la spada sia la parola, solo perché."} },
  { id: "9a9a93b7-aa65-9a9a-8aa6-0000ca5239d2", sisterIndex: 16, author: "Sr. Andreina Stradiotto", topic: "Mary", sentiment: {"en":"She kept the boy and I keep the promise, just because.","it":"Ha custodito il Figlio e io custodisco la promessa, solo perché."} },
  { id: "f573f4bc-8482-f573-1848-000012e2703e", sisterIndex: 17, author: "Sr. Giovanna", topic: "Mary", sentiment: {"en":"Mary is the first thing I was taught to love, just because.","it":"Maria è la prima cosa che mi hanno insegnato ad amare, solo perché."} },
  { id: "a6bc86ad-cf1b-a6bc-8cf1-0000553449b6", sisterIndex: 18, author: "Sr. Consolata", topic: "Mary", sentiment: {"en":"She stood beneath the cross and did not look away, just because.","it":"Rimase sotto la croce e non distolse lo sguardo, solo perché."} },
  { id: "53f53134-bac0-53f5-7bac-0000f9128bf4", sisterIndex: 19, author: "Sr. Adriana", topic: "Mary", sentiment: {"en":"Her sorrow was the size of the world and she held it, just because.","it":"Il suo dolore era grande quanto il mondo e lo tenne, solo perché."} },
  { id: "446c9ae9-895f-446c-6895-0000a19a13b6", sisterIndex: 20, author: "Sr. Sabina Murwana", topic: "Mary", sentiment: {"en":"She believed the impossible and then lived inside it, just because.","it":"Credette l’impossibile e poi ci visse dentro, solo perché."} },
  { id: "3719b2fe-5c7e-3719-05c7-00003c19ee80", sisterIndex: 21, author: "Sr. Susan Chokera", topic: "Mary", sentiment: {"en":"She is the road back to tenderness, just because.","it":"È la strada per tornare alla tenerezza, solo perché."} },
  { id: "ace4f13e-a0e8-ace4-0a0e-0000cb1451d6", sisterIndex: 22, author: "Sr. Susan Kanini", topic: "Mary", sentiment: {"en":"Her yes was one word, and it remade history, just because.","it":"Il suo sì fu una sola parola, e rifesse la storia, solo perché."} },
  { id: "10a87c24-513c-10a8-3513-0000fc0b2d18", sisterIndex: 23, author: "Sr. Cecilia", topic: "Mary", sentiment: {"en":"She nursed the future in an ordinary room, just because.","it":"Allattò il futuro in una stanza ordinaria, solo perché."} },
  { id: "a25862a7-eecb-a258-5eec-000096dd8c6c", sisterIndex: 24, author: "Sr. Lucy Wegoki", topic: "Mary", sentiment: {"en":"Mary is the word for a mother who stays, just because.","it":"Maria è la parola per una madre che resta, solo perché."} },
  { id: "a915c27e-ed64-a915-0ed6-0000a0052f1a", sisterIndex: 25, author: "Sr. Angelica Kinya", topic: "Mary", sentiment: {"en":"She was not promised an easy road, just a faithful one, just because.","it":"Non le fu promessa una strada facile, solo una fedele, solo perché."} },
  { id: "64c9ccab-a323-64c9-0a32-000045396f88", sisterIndex: 26, author: "Sr. Julian", topic: "Mary", sentiment: {"en":"Her joy in Him was so great that it shook the room, just because.","it":"La Sua gioia in Lui era così grande che ha fatto tremare la stanza, solo perché."} },
  { id: "3c874e52-c030-3c87-dc03-00000d2a8e62", sisterIndex: 27, author: "Sr. Maria Carrolla", topic: "Mary", sentiment: {"en":"She is a woman of questions, and I bring her mine, just because.","it":"È una donna di domande, e io le porto le mie, solo perché."} },
  { id: "51bd4d08-4350-51bd-e435-000030730e58", sisterIndex: 28, author: "Sr. Nancy", topic: "Mary", sentiment: {"en":"Mary taught the world to hold what God gives, just because.","it":"Maria insegnò al mondo a tenere ciò che Dio dona, solo perché."} },
  { id: "29200464-75ca-2920-875c-000012e871ae", sisterIndex: 29, author: "Sr. Loredana", topic: "Mary", sentiment: {"en":"She kept the Baby safe and I keep this secret too, just because.","it":"Tenne al sicuro il Bambino e io tengo anche questo segreto, solo perché."} },
  { id: "247e2c6c-bb86-247e-3bb8-0000fc7d97ea", sisterIndex: 30, author: "Sr. Jerusha Nkatha", topic: "Mary", sentiment: {"en":"Her name is on our lips more than her Son’s, and that mystery is grace, just because.","it":"Il suo nome è sulle nostre labbra più di quello del Figlio, e quel mistero è grazia, solo perché."} },
  { id: "2fbb633f-2a8d-2fbb-52a8-00001bee49b2", sisterIndex: 31, author: "Sr. Benedicta", topic: "Mary", sentiment: {"en":"She is the great woman God said would be blessed, just because.","it":"È la grande donna che Dio disse sarebbe stata benedetta, solo perché."} },
  { id: "e5348277-98ab-e534-f98a-000033eb1adc", sisterIndex: 32, author: "Sr. Felicity Makena", topic: "Mary", sentiment: {"en":"Mary gave her only son and kept love, just because.","it":"Maria ha dato il suo unico figlio e ha conservato l’amore, solo perché."} },
  { id: "7b5f7f37-383f-7b5f-c383-000068034708", sisterIndex: 33, author: "Sr. Jiunisia Kaburi", topic: "Mary", sentiment: {"en":"Her patience held a family together, just because.","it":"La sua pazienza tenne insieme una famiglia, solo perché."} },
  { id: "17cdb54e-b36c-17cd-bb36-0000e6260622", sisterIndex: 34, author: "Sr. Margaret N. Kaleli", topic: "Mary", sentiment: {"en":"She waited in the dark and still said yes, just because.","it":"Aspettò nel buio e disse sì lo stesso, solo perché."} },
  { id: "f0daa9b5-f2c3-f0da-6f2c-000085ac5b76", sisterIndex: 35, author: "Sr. Mercy Kathure", topic: "Mary", sentiment: {"en":"She is the mother of us all and I belong, just because.","it":"È la madre di tutti noi e io appartengo, solo perché."} },
  { id: "4cb7c9e7-630f-4cb7-0630-00007777aae8", sisterIndex: 36, author: "Sr. Hellen Murungi", topic: "Mary", sentiment: {"en":"Her sorrow has a sweetness no joy can hold, just because.","it":"Il suo dolore ha una dolcezza che nessuna gioia può contenere, solo perché."} },
  { id: "b044ff5c-7896-b044-c789-0000050887ca", sisterIndex: 37, author: "Sr. Virginia Mwakiuna", topic: "Mary", sentiment: {"en":"Mary is a word I would keep if I kept only one, just because.","it":"Maria è una parola che terrei se potessi tenerne solo una, solo perché."} },
  { id: "228b7775-f7dd-228b-9f7d-00001ab280a8", sisterIndex: 38, author: "Sr. Agatha Mkunda", topic: "Mary", sentiment: {"en":"She did not understand the plan, only the Person, just because.","it":"Non capiva il piano, solo la Persona, solo perché."} },
  { id: "f4e6c8fa-8336-f4e6-c833-000054da4bcc", sisterIndex: 39, author: "Sr. Regina", topic: "Mary", sentiment: {"en":"She said yes in the present tense, just because.","it":"Disse sì al presente, solo perché."} },
  { id: "308ae7b6-ba54-308a-0ba5-00003a9a5de2", sisterIndex: 40, author: "Sr. Dorcas", topic: "Mary", sentiment: {"en":"She is the garden in which my prayers take root, just because.","it":"È il giardino in cui le mie preghiere mettono radice, solo perché."} },
  { id: "2668ad80-d982-2668-2d98-0000cd5a7402", sisterIndex: 41, author: "Sr. Salome Wavinya", topic: "Mary", sentiment: {"en":"She carried Him through the desert and I carry Him through mine, just because.","it":"Lo ha portato attraverso il deserto e io lo porto attraverso il mio, solo perché."} },
  { id: "4e31ee81-18c5-4e31-018c-00006001f644", sisterIndex: 42, author: "Sr. Immaculate", topic: "Mary", sentiment: {"en":"Her humility is the size of her courage, just because.","it":"La sua umiltà è grande quanto il suo coraggio, solo perché."} },
  { id: "d9b93b90-e0a2-d9b9-ce0a-0000e4f5db32", sisterIndex: 43, author: "Sr. Ann", topic: "Mary", sentiment: {"en":"She is the woman God trusted with everything, just because.","it":"È la donna di cui Dio si fidò per tutto, solo perché."} },
  { id: "299483b9-0c71-2994-f0c7-00007b1b8fc8", sisterIndex: 44, author: "Sr. Jane Murigi", topic: "Mary", sentiment: {"en":"Mary is why I dare to call on God as Father, just because.","it":"Maria è la ragione per cui oso rivolgermi a Dio come Padre, solo perché."} },
  { id: "b9d0d995-f811-b9d0-df81-0000a23d2184", sisterIndex: 45, author: "Sr. Joyce Nkirote", topic: "Mary", sentiment: {"en":"She is the quiet yes that the world still rests on, just because.","it":"È il sì silenzioso su cui il mondo ancora poggia, solo perché."} },
  { id: "2b224159-92f1-2b22-092f-0000ec42d3a8", sisterIndex: 46, author: "Sr. Winnie Lopez", topic: "Mary", sentiment: {"en":"Her name is spoken in every language I know, just because.","it":"Il suo nome è pronunciato in ogni lingua che conosco, solo perché."} },
  { id: "7bf01201-f05d-428f-864b-437e4c68a769", sisterIndex: 47, author: "Sr. Teresia Gathoni", topic: "Mary", sentiment: {"en":"She watched over the boy and I watch over this community, just because.","it":"Ha vegliato sul Figlio e io vegli su questa comunità, solo perché."} },
  { id: "34e98945-2525-34e9-2252-0000587bac60", sisterIndex: 48, author: "Sr. Gladys", topic: "Mary", sentiment: {"en":"Mary is the answer I give when words run out, just because.","it":"Maria è la risposta che do quando le parole finiscono, solo perché."} },
  { id: "9bc5ae71-110b-9bc5-0110-0000b375bf7a", sisterIndex: 49, author: "Sr. Martha", topic: "Mary", sentiment: {"en":"She was assumed, and I am carried by that hope, just because.","it":"Fu assunta, e io sono portata da quella speranza, solo perché."} },
  { id: "0f7121f4-af14-0f71-faf1-0000fd3e8ee0", sisterIndex: 50, author: "Sr. Beatrice Kinoti", topic: "Mary", sentiment: {"en":"She kept the covenant with us, just because.","it":"Ha mantenuto l’alleanza con noi, solo perché."} },
  { id: "3ba666f5-9857-3ba6-3985-000052b5fea2", sisterIndex: 51, author: "Madre Nasi", topic: "Mary", sentiment: {"en":"Her story is the one I tell when I am tired of my own, just because.","it":"La sua storia è quella che racconto quando sono stanca della mia, solo perché."} },
  { id: "a1836114-e0a0-a183-fe0a-00007eac81b4", sisterIndex: 52, author: "Sr. Joan", topic: "Mary", sentiment: {"en":"She is the woman in the tent, the sorrow and the song, just because.","it":"È la donna nella tenda, il dolore e il canto, solo perché."} },
  { id: "8bdc84f2-f2ce-8bdc-af2c-0000b9c6763c", sisterIndex: 53, author: "Sr.  Hannah", topic: "Mary", sentiment: {"en":"Mary is the word that means I belong somewhere, just because.","it":"Maria è la parola che significa che appartengo a un posto, solo perché."} },
  { id: "17df2e24-6756-17df-7675-0000bc484972", sisterIndex: 54, author: "Sr. Luisa Makena", topic: "Mary", sentiment: {"en":"She taught her Son mercy, and then He taught the world, just because.","it":"Insegnò al Figlio la misericordia, e poi Lui insegnò al mondo, solo perché."} },
  { id: "62012af4-838a-6201-5838-0000d5b4a97e", sisterIndex: 0, author: "Sr. Purity Nkatha", topic: "Holy Spirit", sentiment: {"en":"Her breath is the wind that moves me when I am stuck, just because.","it":"Il suo respiro è il vento che mi muove quando sono bloccata, solo perché."} },
  { id: "aa6fd25b-4147-aa6f-0414-00004edf931c", sisterIndex: 1, author: "Sr. Mary Japheth", topic: "Holy Spirit", sentiment: {"en":"He is the fire that warms what the sun cannot reach, just because.","it":"È il fuoco che scalda ciò che il sole non raggiunge, solo perché."} },
  { id: "929421d0-e89a-9294-ee89-0000a8cac94a", sisterIndex: 2, author: "Sr. Christine Musoga", topic: "Holy Spirit", sentiment: {"en":"The Spirit teaches without a word and I learn, just because.","it":"Lo Spirito insegna senza parole e io imparo, solo perché."} },
  { id: "5b171f1f-1f8b-5b17-61f8-0000ea010094", sisterIndex: 3, author: "Sr. Priscilla Kanini", topic: "Holy Spirit", sentiment: {"en":"His presence fills the room I thought was empty, just because.","it":"La sua presenza riempie la stanza che credevo vuota, solo perché."} },
  { id: "5881e357-3339-5881-9333-0000de08d06e", sisterIndex: 4, author: "Sr. Aniceta Kaare", topic: "Holy Spirit", sentiment: {"en":"He speaks in a whisper beneath my wanting, just because.","it":"Sussurra sotto il mio desiderio, solo perché."} },
  { id: "68e83f28-5fe4-68e8-55fe-0000079d60cc", sisterIndex: 5, author: "Sr. Anastasia Nkubitu", topic: "Holy Spirit", sentiment: {"en":"The Spirit is patient with my slow obedience, just because.","it":"Lo Spirito è paziente con la mia lenta obbedienza, solo perché."} },
  { id: "e9852506-c666-e985-3c66-00009ad6e360", sisterIndex: 6, author: "Sr. Pauline", topic: "Holy Spirit", sentiment: {"en":"He waits for me in the stillness, just because.","it":"Mi aspetta nella quiete, solo perché."} },
  { id: "a9522fed-ae85-a952-dae8-0000dd2f8168", sisterIndex: 7, author: "Sr. Beth", topic: "Holy Spirit", sentiment: {"en":"His gifts are given freely, and so I offer mine, just because.","it":"I suoi doni sono dati liberamente, e così offro i miei, solo perché."} },
  { id: "9b91e195-2447-9b91-b244-00007ccac5d2", sisterIndex: 8, author: "Sr. Frida Mburugu", topic: "Holy Spirit", sentiment: {"en":"He leads me into the mercy I did not know I had, just because.","it":"Mi conduce nella misericordia che non sapevo di avere, solo perché."} },
  { id: "a20175d1-d29d-a201-fd29-00005d1ea74c", sisterIndex: 9, author: "Sr. Maureen", topic: "Holy Spirit", sentiment: {"en":"The Spirit is my breath and my courage, just because.","it":"Lo Spirito è il mio respiro e il mio coraggio, solo perché."} },
  { id: "9e0207db-08fd-9e02-208f-00009ad00f26", sisterIndex: 10, author: "Sr. Dorothy", topic: "Holy Spirit", sentiment: {"en":"He makes a way where there is none, just because.","it":"Apre una via dove non ce n’è, solo perché."} },
  { id: "b8e2d340-b876-b8e2-ab87-000036b86b36", sisterIndex: 11, author: "Sr. Sofia", topic: "Holy Spirit", sentiment: {"en":"His light is enough for the next step, just because.","it":"La sua luce basta per il passo successivo, solo perché."} },
  { id: "779f52ea-fde4-779f-afde-000001b5af0e", sisterIndex: 12, author: "Sr. Agnes Muthoni", topic: "Holy Spirit", sentiment: {"en":"The Spirit is the water in the desert that keeps us, just because.","it":"Lo Spirito è l’acqua nel deserto che ci mantiene, solo perché."} },
  { id: "213bc418-efc0-213b-7efc-000014cc2bd8", sisterIndex: 13, author: "Sr. Mary Mwikali Matheka", topic: "Holy Spirit", sentiment: {"en":"He dwells in us the way a friend dwells in a home, just because.","it":"Abita in noi come un amico abita in una casa, solo perché."} },
  { id: "c98e6cdd-d07d-c98e-8d07-0000cc06bca0", sisterIndex: 14, author: "Sr. Jane Makanda", topic: "Holy Spirit", sentiment: {"en":"His strength is made perfect in weakness, and I am learning, just because.","it":"La sua forza è resa perfetta nella debolezza, e io sto imparando, solo perché."} },
  { id: "dba2d5ba-ff68-dba2-eff6-0000896c2ad2", sisterIndex: 15, author: "Sr. Rose Kanathi", topic: "Holy Spirit", sentiment: {"en":"The Spirit is the wind that says yes to God in me, just because.","it":"Lo Spirito è il vento che dice sì a Dio in me, solo perché."} },
  { id: "063bf508-3dba-063b-23db-00002ce9c8b2", sisterIndex: 16, author: "Sr. Andreina Stradiotto", topic: "Holy Spirit", sentiment: {"en":"He brings peace that the world cannot give or take, just because.","it":"Porta una pace che il mondo non può dare né togliere, solo perché."} },
  { id: "85e5b919-91f1-85e5-291f-0000779728e8", sisterIndex: 17, author: "Sr. Giovanna", topic: "Holy Spirit", sentiment: {"en":"His work is to make me like Jesus, quietly, just because.","it":"Il suo lavoro è rendermi simile a Gesù, in silenzio, solo perché."} },
  { id: "19194502-0a1c-1919-80a1-0000a7f14f1e", sisterIndex: 18, author: "Sr. Consolata", topic: "Holy Spirit", sentiment: {"en":"The Spirit is a promise kept in my chest, just because.","it":"Lo Spirito è una promessa custodita nel mio cuore, solo perché."} },
  { id: "85e8a3f1-5deb-85e8-b5de-0000cc23fe1a", sisterIndex: 19, author: "Sr. Adriana", topic: "Holy Spirit", sentiment: {"en":"He gives me words when I have none, just because.","it":"Mi dà parole quando non ne ho, solo perché."} },
  { id: "cf767f8e-ae68-cf76-6ae6-00000340d1e6", sisterIndex: 20, author: "Sr. Sabina Murwana", topic: "Holy Spirit", sentiment: {"en":"His breath moves through the whole Church, and I breathe with it, just because.","it":"Il suo respiro attraversa tutta la Chiesa, e io respiro con esso, solo perché."} },
  { id: "859fd62f-3c65-859f-c3c6-00001c93ea4a", sisterIndex: 21, author: "Sr. Susan Chokera", topic: "Holy Spirit", sentiment: {"en":"He is the gentlest teacher I have ever had, just because.","it":"È il maestro più dolce che abbia mai avuto, solo perché."} },
  { id: "5c94fcef-f763-5c94-cf76-0000ce480b8c", sisterIndex: 22, author: "Sr. Susan Kanini", topic: "Holy Spirit", sentiment: {"en":"The Spirit speaks where the world is loudest, just because.","it":"Lo Spirito parla dove il mondo è più rumoroso, solo perché."} },
  { id: "bf8f12e1-33df-bf8f-033d-0000eb6f213e", sisterIndex: 23, author: "Sr. Cecilia", topic: "Holy Spirit", sentiment: {"en":"He gives me courage in the last moment, just because.","it":"Mi dà coraggio all’ultimo momento, solo perché."} },
  { id: "b77acff8-1b2c-b77a-e1b2-00001644d4d4", sisterIndex: 24, author: "Sr. Lucy Wegoki", topic: "Holy Spirit", sentiment: {"en":"His fire warms without burning, just because.","it":"Il suo fuoco scalda senza bruciare, solo perché."} },
  { id: "02d508af-2f57-02d5-e2f5-00000bab27f8", sisterIndex: 25, author: "Sr. Angelica Kinya", topic: "Holy Spirit", sentiment: {"en":"The Spirit is alive in me, and I cannot pretend otherwise, just because.","it":"Lo Spirito è vivo in me, e non posso fingere il contrario, solo perché."} },
  { id: "2e54bc4c-c134-2e54-2c13-0000aba67d78", sisterIndex: 26, author: "Sr. Julian", topic: "Holy Spirit", sentiment: {"en":"He teaches me to forgive the person I have not spoken to, just because.","it":"Mi insegna a perdonare chi non ho più parlato, solo perché."} },
  { id: "33e6dd03-883b-33e6-e883-00000c185538", sisterIndex: 27, author: "Sr. Maria Carrolla", topic: "Holy Spirit", sentiment: {"en":"His fruit grows quietly, and I do not have to force it, just because.","it":"Il suo frutto cresce in silenzio, e non devo forzarlo, solo perché."} },
  { id: "324267a5-1d9b-3242-51d9-000044177a3e", sisterIndex: 28, author: "Sr. Nancy", topic: "Holy Spirit", sentiment: {"en":"The Spirit is my anchor when the waves are high, just because.","it":"Lo Spirito è la mia àncora quando le onde sono alte, solo perché."} },
  { id: "c17ad4a1-58c9-c17a-e58c-00006b348c68", sisterIndex: 29, author: "Sr. Loredana", topic: "Holy Spirit", sentiment: {"en":"He is the breath I pray with, even when no words come, just because.","it":"È il respiro con cui prego, anche quando non vengono parole, solo perché."} },
  { id: "82655989-b47d-8265-ab47-0000553fedf4", sisterIndex: 30, author: "Sr. Jerusha Nkatha", topic: "Holy Spirit", sentiment: {"en":"His presence is enough for the whole of a hard week, just because.","it":"La sua presenza basta per tutta una settimana difficile, solo perché."} },
  { id: "bdac2150-6532-bdac-e653-0000abf24462", sisterIndex: 31, author: "Sr. Benedicta", topic: "Holy Spirit", sentiment: {"en":"He is patient with my two left feet, just because.","it":"È paziente con i miei due piedi sinistri, solo perché."} },
  { id: "aa634b48-eccc-aa63-1ecc-000079f2a784", sisterIndex: 32, author: "Sr. Felicity Makena", topic: "Holy Spirit", sentiment: {"en":"The Spirit gives wisdom to the simple, just because.","it":"Lo Spirito dà saggezza ai semplici, solo perché."} },
  { id: "5d70db88-6f08-5d70-36f0-0000b273b480", sisterIndex: 33, author: "Sr. Jiunisia Kaburi", topic: "Holy Spirit", sentiment: {"en":"He is the voice that says I am loved, over the noise, just because.","it":"È la voce che dice che sono amata, sopra il rumore, solo perché."} },
  { id: "fded93ff-7c6f-fded-a7c6-0000fb97ef90", sisterIndex: 34, author: "Sr. Margaret N. Kaleli", topic: "Holy Spirit", sentiment: {"en":"His gift of tears has been a mercy more than once, just because.","it":"Il suo dono delle lacrime è stata una misericordia più di una volta, solo perché."} },
  { id: "47c1232a-ec14-47c1-6ec1-00005637cf3e", sisterIndex: 35, author: "Sr. Mercy Kathure", topic: "Holy Spirit", sentiment: {"en":"The Spirit is the water in the well, and I thirst, just because.","it":"Lo Spirito è l’acqua del pozzo, e io ho sete, solo perché."} },
  { id: "f12421b8-ad78-f124-ead7-0000b40a8cc0", sisterIndex: 36, author: "Sr. Hellen Murungi", topic: "Holy Spirit", sentiment: {"en":"He is a river I keep returning to, just because.","it":"È un fiume a cui torno sempre, solo perché."} },
  { id: "20b9d4b9-41ad-20b9-641a-0000393f9514", sisterIndex: 37, author: "Sr. Virginia Mwakiuna", topic: "Holy Spirit", sentiment: {"en":"The Spirit lifts me when my own strength runs out, just because.","it":"Lo Spirito mi solleva quando la mia forza si esaurisce, solo perché."} },
  { id: "fbd7286a-fb22-fbd7-1fb2-00008ec6d348", sisterIndex: 38, author: "Sr. Agatha Mkunda", topic: "Holy Spirit", sentiment: {"en":"He is a beginning that never ends, just because.","it":"È un inizio che non finisce mai, solo perché."} },
  { id: "07186b8b-bd8d-0718-abd8-000023c2d606", sisterIndex: 39, author: "Sr. Regina", topic: "Holy Spirit", sentiment: {"en":"His love is poured out like water, and I am thirsty, just because.","it":"Il suo amore è versato come acqua, e io ho sete, solo perché."} },
  { id: "db89b7c7-0027-db89-6002-0000050fb7e0", sisterIndex: 40, author: "Sr. Dorcas", topic: "Holy Spirit", sentiment: {"en":"The Spirit is the wind behind the sails, just because.","it":"Lo Spirito è il vento dietro la vela, solo perché."} },
  { id: "10c5589d-70f1-10c5-970f-0000a41c286c", sisterIndex: 41, author: "Sr. Salome Wavinya", topic: "Holy Spirit", sentiment: {"en":"He leads me out of myself and into the world, just because.","it":"Mi conduce fuori da me e nel mondo, solo perché."} },
  { id: "80e19406-8cda-80e1-08cd-000019f118dc", sisterIndex: 42, author: "Sr. Immaculate", topic: "Holy Spirit", sentiment: {"en":"His peace is not the absence of trouble, just because.","it":"La sua pace non è l’assenza dei problemi, solo perché."} },
  { id: "494dbc6d-1251-494d-a125-00003c47ae3c", sisterIndex: 43, author: "Sr. Ann", topic: "Holy Spirit", sentiment: {"en":"The Spirit is alive and speaking, and I have heard Him, just because.","it":"Lo Spirito è vivo e parla, e L’ho ascoltato, solo perché."} },
  { id: "6fb65b1e-bc5e-6fb6-bbc5-000049ade740", sisterIndex: 44, author: "Sr. Jane Murigi", topic: "Holy Spirit", sentiment: {"en":"He is the strength in my weakness, just because.","it":"È la forza nella mia debolezza, solo perché."} },
  { id: "f6bf1a0a-3b3e-f6bf-83b3-00002dd72134", sisterIndex: 45, author: "Sr. Joyce Nkirote", topic: "Holy Spirit", sentiment: {"en":"The Spirit is the reason I can say I am not alone, just because.","it":"Lo Spirito è il motivo per cui posso dire di non essere sola, solo perché."} },
  { id: "52ffe8be-3fde-52ff-83fd-0000be17d760", sisterIndex: 46, author: "Sr. Winnie Lopez", topic: "Holy Spirit", sentiment: {"en":"His fruit is visible in me, slowly, just because.","it":"Il suo frutto è visibile in me, lentamente, solo perché."} },
  { id: "a9156c28-8b50-a915-a8b5-0000695fe778", sisterIndex: 47, author: "Sr. Teresia Gathoni", topic: "Holy Spirit", sentiment: {"en":"He is the fire that warms my hands on a cold morning, just because.","it":"È il fuoco che scalda le mie mani in un mattino freddo, solo perché."} },
  { id: "7e337dfa-f5fa-7e33-bf5f-0000bc988800", sisterIndex: 48, author: "Sr. Gladys", topic: "Holy Spirit", sentiment: {"en":"The Spirit is my constant, just because.","it":"Lo Spirito è la mia costanza, solo perché."} },
  { id: "0d0eb3f9-9d59-4053-9008-4dd587efed4d", sisterIndex: 49, author: "Sr. Martha", topic: "Holy Spirit", sentiment: {"en":"He has never once left me, just because.","it":"Non mi ha mai lasciata, nemmeno una volta, solo perché."} },
  { id: "74ec3031-e667-74ec-3e66-0000106fd656", sisterIndex: 50, author: "Sr. Beatrice Kinoti", topic: "Holy Spirit", sentiment: {"en":"His breath is in the Church, in the room, in me, just because.","it":"Il suo respiro è nella Chiesa, nella stanza, in me, solo perché."} },
  { id: "ccd1faea-c050-ccd1-4c05-0000ac453aba", sisterIndex: 51, author: "Madre Nasi", topic: "Holy Spirit", sentiment: {"en":"The Spirit is the oil that keeps the lamp burning, just because.","it":"Lo Spirito è l’olio che mantiene accesa la lampada, solo perché."} },
  { id: "fc872e51-238b-fc87-d238-0000a07a0dda", sisterIndex: 52, author: "Sr. Joan", topic: "Holy Spirit", sentiment: {"en":"He teaches me to give myself away, just because.","it":"Mi insegna a donare me stessa, solo perché."} },
  { id: "6aaaa523-8d55-6aaa-b8d5-00005ed12876", sisterIndex: 53, author: "Sr.  Hannah", topic: "Holy Spirit", sentiment: {"en":"He is alive in the poor and in me, just because.","it":"È vivo nei poveri e in me, solo perché."} },
  { id: "942798e1-d5ed-9427-bd5e-0000b47c4d0c", sisterIndex: 54, author: "Sr. Luisa Makena", topic: "Holy Spirit", sentiment: {"en":"The Spirit is enough for today, and today is enough, just because.","it":"Lo Spirito basta per oggi, e oggi basta, solo perché."} },
  { id: "248c54b6-6ed8-248c-86ed-000000943a6e", sisterIndex: 0, author: "Sr. Purity Nkatha", topic: "Joy", sentiment: {"en":"A glad heart is the loudest room I have ever lived in, just because.","it":"Un cuore contento è la stanza più rumorosa in cui abbia mai vissuto, solo perché."} },
  { id: "b177cf79-a5b5-b177-2a5b-00006f656acc", sisterIndex: 1, author: "Sr. Mary Japheth", topic: "Joy", sentiment: {"en":"Joy arrived uninvited, and I stopped asking for permission, just because.","it":"La gioia è arrivata senza essere invitata, e ho smesso di chiedere il permesso, solo perché."} },
  { id: "5553298a-ede8-5553-dede-00000fdec462", sisterIndex: 2, author: "Sr. Christine Musoga", topic: "Joy", sentiment: {"en":"I have decided joy is a decision, just because.","it":"Ho deciso che la gioia è una decisione, solo perché."} },
  { id: "d31b0375-aa79-d31b-9aa7-0000dba2a90c", sisterIndex: 3, author: "Sr. Priscilla Kanini", topic: "Joy", sentiment: {"en":"The ordinary day is enough for me now, just because.","it":"Il giorno ordinario mi basta ora, solo perché."} },
  { id: "c2bc008d-1ce7-c2bc-51ce-000041a91c6a", sisterIndex: 4, author: "Sr. Aniceta Kaare", topic: "Joy", sentiment: {"en":"Joy is stronger when it is shared, just because.","it":"La gioia è più forte quando è condivisa, solo perché."} },
  { id: "764c8be2-e972-764c-ee97-000047e26290", sisterIndex: 5, author: "Sr. Anastasia Nkubitu", topic: "Joy", sentiment: {"en":"I laugh more than I did, and I know why, just because.","it":"Rido più di prima, e so perché, solo perché."} },
  { id: "eac8d974-1f34-eac8-d1f3-0000b4a5c640", sisterIndex: 6, author: "Sr. Pauline", topic: "Joy", sentiment: {"en":"God is good and I have stopped needing proof, just because.","it":"Dio è buono e ho smesso di cercare prove, solo perché."} },
  { id: "d84ca53f-dbb3-d84c-8dbb-0000e4047e8c", sisterIndex: 7, author: "Sr. Beth", topic: "Joy", sentiment: {"en":"Joy is not happiness; it is deeper and it survives, just because.","it":"La gioia non è felicità; è più profonda e sopravvive, solo perché."} },
  { id: "a4b4aec7-68b5-a4b4-868b-00006abcc672", sisterIndex: 8, author: "Sr. Frida Mburugu", topic: "Joy", sentiment: {"en":"I have chosen to be glad, just because.","it":"Ho scelto di essere contenta, solo perché."} },
  { id: "6dfb065b-76cb-6dfb-876c-000077d37090", sisterIndex: 9, author: "Sr. Maureen", topic: "Joy", sentiment: {"en":"The best day I ever had was an ordinary one, just because.","it":"Il giorno migliore che ho avuto è stato uno qualunque, solo perché."} },
  { id: "cf9ed4f9-492b-cf9e-2492-0000fc6c9dd2", sisterIndex: 10, author: "Sr. Dorothy", topic: "Joy", sentiment: {"en":"Something in me has been unburdened and I did not do it, just because.","it":"Qualcosa in me è stato liberato e non l’ho fatto io, solo perché."} },
  { id: "5f6077ba-4b44-5f60-b4b4-0000a5ab3cfe", sisterIndex: 11, author: "Sr. Sofia", topic: "Joy", sentiment: {"en":"Joy is allowed to be here, just because.","it":"La gioia ha il permesso di essere qui, solo perché."} },
  { id: "5b73c440-4772-5b73-9477-0000097a8332", sisterIndex: 12, author: "Sr. Agnes Muthoni", topic: "Joy", sentiment: {"en":"I have stopped waiting for life to begin, just because.","it":"Ho smesso di aspettare che la vita cominci, solo perché."} },
  { id: "d0a18392-06ce-d0a1-b06c-0000b94a855c", sisterIndex: 13, author: "Sr. Mary Mwikali Matheka", topic: "Joy", sentiment: {"en":"There is more good here than I have been counting, just because.","it":"C’è più bene qui di quanto io abbia contato, solo perché."} },
  { id: "6803e72f-40ab-6803-e40a-00008b8da784", sisterIndex: 14, author: "Sr. Jane Makanda", topic: "Joy", sentiment: {"en":"My soul is glad and I do not need a reason, just because.","it":"La mia anima è contenta e non mi serve un motivo, solo perché."} },
  { id: "99c1d1d0-3776-99c1-9377-00001008e6a6", sisterIndex: 15, author: "Sr. Rose Kanathi", topic: "Joy", sentiment: {"en":"I have found joy in the small and the large, just because.","it":"Ho trovato gioia nelle cose piccole e in quelle grandi, solo perché."} },
  { id: "aaf3c8c2-5708-aaf3-5570-00004a369fca", sisterIndex: 16, author: "Sr. Andreina Stradiotto", topic: "Joy", sentiment: {"en":"The good news is that this is not temporary, just because.","it":"La buona notizia è che questo non è temporaneo, solo perché."} },
  { id: "adb92763-f69f-adb9-9f69-00002400d1fc", sisterIndex: 17, author: "Sr. Giovanna", topic: "Joy", sentiment: {"en":"I have been given a glad heart, just because.","it":"Mi è stato dato un cuore contento, solo perché."} },
  { id: "5db2a978-beaa-5db2-0bea-000025e217d2", sisterIndex: 18, author: "Sr. Consolata", topic: "Joy", sentiment: {"en":"Joy is the natural state I keep returning to, just because.","it":"La gioia è lo stato naturale a cui torno sempre, solo perché."} },
  { id: "f887447b-84d9-f887-384d-000035e4c0a2", sisterIndex: 19, author: "Sr. Adriana", topic: "Joy", sentiment: {"en":"I can be sorrowful and still glad, and both are true, just because.","it":"Posso essere triste e insieme contenta, ed entrambe le cose sono vere, solo perché."} },
  { id: "e6bcf4bc-4676-e6bc-f467-0000e193b2ca", sisterIndex: 20, author: "Sr. Sabina Murwana", topic: "Joy", sentiment: {"en":"The people around me make the gladness bigger, just because.","it":"Le persone intorno a me rendono più grande la contentezza, solo perché."} },
  { id: "e43b3bc5-3593-e43b-e359-000053850e56", sisterIndex: 21, author: "Sr. Susan Chokera", topic: "Joy", sentiment: {"en":"I have learned that joy is a duty, just because.","it":"Ho imparato che la gioia è un dovere, solo perché."} },
  { id: "61d2ed05-9151-61d2-2915-0000c2607c54", sisterIndex: 22, author: "Sr. Susan Kanini", topic: "Joy", sentiment: {"en":"My gladness survives the hard day, just because.","it":"La mia contentezza sopravvive alla giornata difficile, solo perché."} },
  { id: "33db34eb-9f4d-33db-29f4-00000e79aba6", sisterIndex: 23, author: "Sr. Cecilia", topic: "Joy", sentiment: {"en":"God is joy, and so I am allowed to be, just because.","it":"Dio è gioia, e così è permesso a me esserlo, solo perché."} },
  { id: "92923d72-69ba-9292-269b-0000f5a054c8", sisterIndex: 24, author: "Sr. Lucy Wegoki", topic: "Joy", sentiment: {"en":"I have joy even without a reason, which is the best kind, just because.","it":"Ho gioia anche senza un motivo, che è la specie migliore, solo perché."} },
  { id: "cdf69e45-4dc5-cdf6-94dc-000000efd380", sisterIndex: 25, author: "Sr. Angelica Kinya", topic: "Joy", sentiment: {"en":"I greet the day before I have earned it, just because.","it":"Saluto il giorno prima di averlo guadagnato, solo perché."} },
  { id: "852c288e-ccc2-852c-1ccc-00009bede44c", sisterIndex: 26, author: "Sr. Julian", topic: "Joy", sentiment: {"en":"The heavy thing has become light, and I did nothing, just because.","it":"La cosa pesante è diventata leggera, e io non ho fatto nulla, solo perché."} },
  { id: "df61a321-d129-df61-0d12-00005d417208", sisterIndex: 27, author: "Sr. Maria Carrolla", topic: "Joy", sentiment: {"en":"I can celebrate the ordinary, just because.","it":"So festeggiare l’ordinario, solo perché."} },
  { id: "3ae68b57-6289-3ae6-b628-0000052de9de", sisterIndex: 28, author: "Sr. Nancy", topic: "Joy", sentiment: {"en":"Joy is stronger when it comes through tears, just because.","it":"La gioia è più forte quando arriva attraverso le lacrime, solo perché."} },
  { id: "0b6a212b-2c77-0b6a-e2c7-0000aea40d5c", sisterIndex: 29, author: "Sr. Loredana", topic: "Joy", sentiment: {"en":"I have a gladness that no loss can take entirely, just because.","it":"Ho una contentezza che nessuna perdita può portare via del tutto, solo perché."} },
  { id: "3ef39ed3-a4ab-3ef3-aa4a-0000f1d93a78", sisterIndex: 30, author: "Sr. Jerusha Nkatha", topic: "Joy", sentiment: {"en":"I was made for gladness and I am coming back to it, just because.","it":"Sono stata fatta per la contentezza e sto tornando a essa, solo perché."} },
  { id: "5bf8b90a-b180-5bf8-9b18-0000aca1088a", sisterIndex: 31, author: "Sr. Benedicta", topic: "Joy", sentiment: {"en":"There is music in the ordinary, and I hear it, just because.","it":"C’è musica nell’ordinario, e io la sento, solo perché."} },
  { id: "f90cc082-9f5a-f90c-b9f5-0000e5275fd8", sisterIndex: 32, author: "Sr. Felicity Makena", topic: "Joy", sentiment: {"en":"I laugh at myself and it heals me, just because.","it":"Rido di me stessa e mi guarisce, solo perché."} },
  { id: "12bc5f42-cb16-12bc-7cb1-0000e09b9454", sisterIndex: 33, author: "Sr. Jiunisia Kaburi", topic: "Joy", sentiment: {"en":"My glad heart is a gift I did not earn, just because.","it":"Il mio cuore contento è un dono che non ho meritato, solo perché."} },
  { id: "ba977555-b1dd-ba97-3b1d-00000934c488", sisterIndex: 34, author: "Sr. Margaret N. Kaleli", topic: "Joy", sentiment: {"en":"The good things are not past, just because.","it":"Le cose buone non sono nel passato, solo perché."} },
  { id: "2ff8d700-e3a2-2ff8-1e3a-0000f7c934a2", sisterIndex: 35, author: "Sr. Mercy Kathure", topic: "Joy", sentiment: {"en":"I have joy to give, and giving it doubles it, just because.","it":"Ho gioia da dare, e dandola raddoppia, solo perché."} },
  { id: "3cc2c0b2-9f86-3cc2-99f8-00009b7b5f34", sisterIndex: 36, author: "Sr. Hellen Murungi", topic: "Joy", sentiment: {"en":"I have stopped measuring my days, and they fill up, just because.","it":"Ho smesso di misurare le mie giornate, e si riempiono, solo perché."} },
  { id: "e822ad83-3fdb-e822-73fd-000098959258", sisterIndex: 37, author: "Sr. Virginia Mwakiuna", topic: "Joy", sentiment: {"en":"The kingdom is here, in this, now, and that makes me glad, just because.","it":"Il regno è qui, in questo, adesso, e questo mi rende contenta, solo perché."} },
  { id: "5dac69c0-0d70-5dac-30d7-00008a6f64b0", sisterIndex: 38, author: "Sr. Agatha Mkunda", topic: "Joy", sentiment: {"en":"I am happy in the way that has nothing to do with my circumstances, just because.","it":"Sono contenta in un modo che non ha a che fare con le mie circostanze, solo perché."} },
  { id: "53ad18e9-47bb-53ad-947b-000033d45f52", sisterIndex: 39, author: "Sr. Regina", topic: "Joy", sentiment: {"en":"There is a joy in being loved that I did not have to earn, just because.","it":"C’è una gioia nell’essere amata che non ho dovuto guadagnarmi, solo perché."} },
  { id: "25bfdebd-d095-25bf-cd09-000000830e28", sisterIndex: 40, author: "Sr. Dorcas", topic: "Joy", sentiment: {"en":"I will be glad again, and again, just because.","it":"Sarò contenta ancora, e ancora, solo perché."} },
  { id: "3542de6f-359f-3542-d359-0000d32febf0", sisterIndex: 41, author: "Sr. Salome Wavinya", topic: "Joy", sentiment: {"en":"The small mercies are actually the big ones, just because.","it":"Le piccole misericordie sono in realtà le grandi, solo perché."} },
  { id: "b3e26874-fa28-b3e2-9fa2-0000860b925c", sisterIndex: 42, author: "Sr. Immaculate", topic: "Joy", sentiment: {"en":"My joy is not fragile, just because.","it":"La mia gioia non è fragile, solo perché."} },
  { id: "0e8521bf-52ff-0e85-d52f-00008f287340", sisterIndex: 43, author: "Sr. Ann", topic: "Joy", sentiment: {"en":"I have stopped asking why, and started asking what is good, just because.","it":"Ho smesso di chiedermi perché e ho iniziato a chiedermi che cosa è buono, solo perché."} },
  { id: "2e7c97cc-d82c-2e7c-fd82-0000d9634fe0", sisterIndex: 44, author: "Sr. Jane Murigi", topic: "Joy", sentiment: {"en":"Something in the garden of my life has been watered, just because.","it":"Qualcosa nel giardino della mia vita è stato innaffiato, solo perché."} },
  { id: "d0b9bc60-c30c-d0b9-8c30-000015817f6c", sisterIndex: 45, author: "Sr. Joyce Nkirote", topic: "Joy", sentiment: {"en":"The people who share my gladness are the ones I keep, just because.","it":"Le persone che condividono la mia contentezza sono quelle che conservo, solo perché."} },
  { id: "732e79ec-0bac-732e-b0ba-000043057240", sisterIndex: 46, author: "Sr. Winnie Lopez", topic: "Joy", sentiment: {"en":"I have a joy that does not need an audience, just because.","it":"Ho una gioia che non ha bisogno di pubblico, solo perché."} },
  { id: "241518e2-4c5e-2415-54c5-0000faf054bc", sisterIndex: 47, author: "Sr. Teresia Gathoni", topic: "Joy", sentiment: {"en":"The best gift I can give is gladness, just because.","it":"Il dono migliore che posso fare è la contentezza, solo perché."} },
  { id: "64bbd690-f748-64bb-1f74-0000407a21d8", sisterIndex: 48, author: "Sr. Gladys", topic: "Joy", sentiment: {"en":"I am learning that joy is a practice, not a mood, just because.","it":"Sto imparando che la gioia è una pratica, non un umore, solo perché."} },
  { id: "91935e24-e07a-9193-1e07-00002f12be5e", sisterIndex: 49, author: "Sr. Martha", topic: "Joy", sentiment: {"en":"Something good happened and I let myself have it, just because.","it":"È successo qualcosa di buono e mi sono permesso di goderne, solo perché."} },
  { id: "dffddf3b-5ed5-dffd-c5ed-0000767181ee", sisterIndex: 50, author: "Sr. Beatrice Kinoti", topic: "Joy", sentiment: {"en":"The world is wounded but not finished, and I am glad of that, just because.","it":"Il mondo è ferito ma non finito, e io sono contenta di questo, solo perché."} },
  { id: "2a996c40-a15e-2a99-ba15-00008a62cd1e", sisterIndex: 51, author: "Madre Nasi", topic: "Joy", sentiment: {"en":"I have joy even in the waiting, just because.","it":"Ho gioia anche nell’attesa, solo perché."} },
  { id: "3ed42edb-2e79-3ed4-f2e7-000034ab00a2", sisterIndex: 52, author: "Sr. Joan", topic: "Joy", sentiment: {"en":"There is more to celebrate than to grieve, just because.","it":"C’è più da celebrare che da piangere, solo perché."} },
  { id: "2c938a2c-1b38-4e2f-bec0-2f231d009320", sisterIndex: 53, author: "Sr.  Hannah", topic: "Joy", sentiment: {"en":"I am glad to be here, in this body, in this moment, just because.","it":"Sono contenta di essere qui, in questo corpo, in questo momento, solo perché."} },
  { id: "9140faeb-3c1b-9140-d3c1-000025fdc6f0", sisterIndex: 54, author: "Sr. Luisa Makena", topic: "Joy", sentiment: {"en":"The gladness is a door, and I keep it open, just because.","it":"La contentezza è una porta, e io la tengo aperta, solo perché."} },
  { id: "1f6cfb59-e775-1f6c-be77-00009f371c2c", sisterIndex: 0, author: "Sr. Purity Nkatha", topic: "Providence", sentiment: {"en":"I have been carried through every loss by hands I never saw, just because.","it":"Sono stata portata attraverso ogni perdita da mani che non ho mai visto, solo perché."} },
  { id: "562b2148-59ec-562b-059e-0000da3b78a4", sisterIndex: 1, author: "Sr. Mary Japheth", topic: "Providence", sentiment: {"en":"I have not been given an explanation, but I have been given a keeper, just because.","it":"Non mi è stata data una spiegazione, ma mi è stato dato un custode, solo perché."} },
  { id: "bd4eed2d-7aa5-bd4e-47aa-00007f4a9788", sisterIndex: 2, author: "Sr. Christine Musoga", topic: "Providence", sentiment: {"en":"The thing I feared did not come, and the thing I did not fear became a gift, just because.","it":"Quello che temevo non è venuto, e quello che non temevo è diventato un dono, solo perché."} },
  { id: "e84f8794-4db8-e84f-84db-0000df27ca2c", sisterIndex: 3, author: "Sr. Priscilla Kanini", topic: "Providence", sentiment: {"en":"I have been given enough for today, just because.","it":"Mi è stato dato abbastanza per oggi, solo perché."} },
  { id: "7c63a4bc-b042-7c63-9b04-00000ada14fe", sisterIndex: 4, author: "Sr. Aniceta Kaare", topic: "Providence", sentiment: {"en":"I do not see the road, only that I am on it, just because.","it":"Non vedo la strada, vedo solo che sono su di essa, solo perché."} },
  { id: "70faf595-e703-70fa-be70-0000b0611296", sisterIndex: 5, author: "Sr. Anastasia Nkubitu", topic: "Providence", sentiment: {"en":"Every door that closed had someone standing behind it, just because.","it":"Ogni porta che si è chiusa aveva qualcuno in piedi dietro, solo perché."} },
  { id: "106878c7-df09-1068-cdf0-0000bd34a7ce", sisterIndex: 6, author: "Sr. Pauline", topic: "Providence", sentiment: {"en":"I have been kept and I did nothing to deserve it, just because.","it":"Sono stata custodita e non ho fatto nulla per meritarlo, solo perché."} },
  { id: "6340f486-4d26-6340-b4d2-00008e0bb9a0", sisterIndex: 7, author: "Sr. Beth", topic: "Providence", sentiment: {"en":"The delay was protection, though it did not feel like it, just because.","it":"Il ritardo era protezione, anche se non lo sembrava, solo perché."} },
  { id: "c0db5ede-c2ec-c0db-fc2e-000075e49c32", sisterIndex: 8, author: "Sr. Frida Mburugu", topic: "Providence", sentiment: {"en":"I have been given people who arrived exactly in time, just because.","it":"Mi sono state date persone arrivate esattamente in tempo, solo perché."} },
  { id: "7a466112-6f6e-7a46-86f6-0000bf1e0e7c", sisterIndex: 9, author: "Sr. Maureen", topic: "Providence", sentiment: {"en":"I do not understand the plan, but I trust the hand, just because.","it":"Non capisco il piano, ma confido nella mano, solo perché."} },
  { id: "bfe785c8-6a8e-bfe7-f6a8-00005bf8ef46", sisterIndex: 10, author: "Sr. Dorothy", topic: "Providence", sentiment: {"en":"Something is being prepared that I cannot see yet, just because.","it":"Si sta preparando qualcosa che ancora non vedo, solo perché."} },
  { id: "ca7f5e3d-5939-ca7f-b593-000032940704", sisterIndex: 11, author: "Sr. Sofia", topic: "Providence", sentiment: {"en":"I have been given a life, and I do not know by whose design, just because.","it":"Mi è stata data una vita, e non so per disegno di chi, solo perché."} },
  { id: "8d794453-4103-8d79-0410-0000ed390550", sisterIndex: 12, author: "Sr. Agnes Muthoni", topic: "Providence", sentiment: {"en":"The gift was wrapped in the loss, and I was too sad to open it, just because.","it":"Il dono era avvolto nella perdita, e io ero troppo triste per aprirlo, solo perché."} },
  { id: "26950025-0597-2695-7059-00002cd205b2", sisterIndex: 13, author: "Sr. Mary Mwikali Matheka", topic: "Providence", sentiment: {"en":"I am being formed into something I will only recognise later, just because.","it":"Sto essendo plasmata in qualcosa che riconoscerò solo più avanti, solo perché."} },
  { id: "2b1258d6-a10e-2b12-ca10-00002f2ef9d8", sisterIndex: 14, author: "Sr. Jane Makanda", topic: "Providence", sentiment: {"en":"I have been given more than I asked for and less than I feared, just because.","it":"Ho ricevuto più di quanto chiedessi e meno di quanto temessi, solo perché."} },
  { id: "c8239fc3-ee8f-c823-5ee8-00002796714c", sisterIndex: 15, author: "Sr. Rose Kanathi", topic: "Providence", sentiment: {"en":"The road went through the valley because it was the only way, just because.","it":"La strada passava per la valle perché era l’unica via, solo perché."} },
  { id: "2e9ae0f5-0205-2e9a-0020-0000b9bae2f0", sisterIndex: 16, author: "Sr. Andreina Stradiotto", topic: "Providence", sentiment: {"en":"I have been given roots before I could see the tree, just because.","it":"Mi sono state date radici prima di vedere l’albero, solo perché."} },
  { id: "cec88c8a-6a6a-cec8-a6a6-00004e72e6e0", sisterIndex: 17, author: "Sr. Giovanna", topic: "Providence", sentiment: {"en":"I was not spared, but I was carried, just because.","it":"Non sono stata risparmiata, ma sono stata portata, solo perché."} },
  { id: "a144527b-63ab-a144-a63a-0000a25e31d0", sisterIndex: 18, author: "Sr. Consolata", topic: "Providence", sentiment: {"en":"Someone has been holding the other end of this rope, just because.","it":"Qualcuno ha tenuto l’altro capo di questa corda, solo perché."} },
  { id: "d4afffb2-60d8-d4af-a60d-000036259f6a", sisterIndex: 19, author: "Sr. Adriana", topic: "Providence", sentiment: {"en":"I have been given bread on the days I thought there would be none, just because.","it":"Ho ricevuto il pane nei giorni in cui pensavo non ce ne sarebbe stato, solo perché."} },
  { id: "3140253f-bb8f-3140-6bb8-0000ade69eb0", sisterIndex: 20, author: "Sr. Sabina Murwana", topic: "Providence", sentiment: {"en":"The waiting has a purpose even when it has no explanation, just because.","it":"L’attesa ha uno scopo anche quando non ha una spiegazione, solo perché."} },
  { id: "ecd7ad04-2ec6-ecd7-42ec-000040f383c2", sisterIndex: 21, author: "Sr. Susan Chokera", topic: "Providence", sentiment: {"en":"I have been given a place that fits, even when I was smaller than it, just because.","it":"Mi è stato dato un posto che mi contiene, anche quando ero più piccola, solo perché."} },
  { id: "55170544-fb40-5517-3fb4-000040c4fe04", sisterIndex: 22, author: "Sr. Susan Kanini", topic: "Providence", sentiment: {"en":"What I called waste has been building something, just because.","it":"Ciò che ho chiamato spreco sta costruendo qualcosa, solo perché."} },
  { id: "313e42c2-87b4-313e-f87b-0000a641c576", sisterIndex: 23, author: "Sr. Cecilia", topic: "Providence", sentiment: {"en":"I have been given seasons, and every one was needed, just because.","it":"Mi sono state date le stagioni, e ogni stagione serviva, solo perché."} },
  { id: "970f1485-fadb-970f-bfad-0000ba04ee5e", sisterIndex: 24, author: "Sr. Lucy Wegoki", topic: "Providence", sentiment: {"en":"I do not have to be in a hurry; the timing is not mine, just because.","it":"Non devo avere fretta; i tempi non sono i miei, solo perché."} },
  { id: "23774084-c81c-2377-ac81-0000951d8898", sisterIndex: 25, author: "Sr. Angelica Kinya", topic: "Providence", sentiment: {"en":"Something was rescued because I prayed, just because.","it":"Qualcosa è stato salvato perché ho pregato, solo perché."} },
  { id: "7ca828a1-fef3-7ca8-bfef-0000a3f3d652", sisterIndex: 26, author: "Sr. Julian", topic: "Providence", sentiment: {"en":"I have been given a tomorrow even when I could not see it, just because.","it":"Mi è stato dato un domani anche quando non potevo vederlo, solo perché."} },
  { id: "005891c0-13c8-0058-013c-00009dd88208", sisterIndex: 27, author: "Sr. Maria Carrolla", topic: "Providence", sentiment: {"en":"The people who failed me were also used, just because.","it":"Le persone che mi hanno delusa sono state usate anch’esse, solo perché."} },
  { id: "3aa5890e-ebe8-3aa5-9ebe-0000b0dc62e6", sisterIndex: 28, author: "Sr. Nancy", topic: "Providence", sentiment: {"en":"I have been given a hard yes and a soft no, just because.","it":"Ho ricevuto un sì difficile e un no dolce, solo perché."} },
  { id: "5e52e102-a4f2-5e52-ea4f-000085bc45f0", sisterIndex: 29, author: "Sr. Loredana", topic: "Providence", sentiment: {"en":"There is a hand in the dark and I have learned to take it, just because.","it":"C’è una mano nel buio e ho imparato a prenderla, solo perché."} },
  { id: "1fb9031a-4d0e-1fb9-34d0-0000718a4e14", sisterIndex: 30, author: "Sr. Jerusha Nkatha", topic: "Providence", sentiment: {"en":"I have been given the grace of not knowing, just because.","it":"Mi è stata data la grazia di non sapere, solo perché."} },
  { id: "66b49fad-c66d-66b4-8c66-0000a9cc59c0", sisterIndex: 31, author: "Sr. Benedicta", topic: "Providence", sentiment: {"en":"Something I feared has become a place of shelter, just because.","it":"Qualcosa che temevo è diventato un rifugio, solo perché."} },
  { id: "0ccc64b5-17bb-0ccc-917b-00008ca5730e", sisterIndex: 32, author: "Sr. Felicity Makena", topic: "Providence", sentiment: {"en":"I was carried through a year I could not have walked, just because.","it":"Sono stata portata attraverso un anno che non avrei potuto percorrere, solo perché."} },
  { id: "fedc7075-656f-fedc-8656-0000a224151a", sisterIndex: 33, author: "Sr. Jiunisia Kaburi", topic: "Providence", sentiment: {"en":"I have been given back to myself, better than before, just because.","it":"Sono stata restituita a me stessa, migliore di prima, solo perché."} },
  { id: "835b21f4-a564-835b-2a56-0000e9298490", sisterIndex: 34, author: "Sr. Margaret N. Kaleli", topic: "Providence", sentiment: {"en":"The life I have is the one that was given, and I am learning to love it, just because.","it":"La vita che ho è quella che mi è stata data, e sto imparando ad amarla, solo perché."} },
  { id: "fbc13913-f793-fbc1-6f79-0000bf47ce80", sisterIndex: 35, author: "Sr. Mercy Kathure", topic: "Providence", sentiment: {"en":"I have been given a family that is not the one I planned, just because.","it":"Mi è stata data una famiglia che non è quella che avevo pianificato, solo perché."} },
  { id: "8ec0aac5-9cbf-8ec0-59cb-0000c875367a", sisterIndex: 36, author: "Sr. Hellen Murungi", topic: "Providence", sentiment: {"en":"I am kept, and the keeping has never once failed, just because.","it":"Sono custodita, e la custodia non ha mai fallito, solo perché."} },
  { id: "7a095a2a-a09e-7a09-ea09-00000127fab4", sisterIndex: 37, author: "Sr. Virginia Mwakiuna", topic: "Providence", sentiment: {"en":"The quiet years were not wasted; they were the foundation, just because.","it":"Gli anni tranquilli non sono stati sprecati; erano la fondazione, solo perché."} },
  { id: "09fd88d3-e43d-09fd-be43-000090b66cee", sisterIndex: 38, author: "Sr. Agatha Mkunda", topic: "Providence", sentiment: {"en":"I have been given a peace before the answer, just because.","it":"Mi è stata data una pace prima della risposta, solo perché."} },
  { id: "d66d1118-cc3e-d66d-0cc3-0000edfddd26", sisterIndex: 39, author: "Sr. Regina", topic: "Providence", sentiment: {"en":"Something lost was returned to me, and it was enough, just because.","it":"Qualcosa di perso mi è stato restituito, ed è bastato, solo perché."} },
  { id: "8c18470c-0e8c-8c18-d0e8-00001d654980", sisterIndex: 40, author: "Sr. Dorcas", topic: "Providence", sentiment: {"en":"I have been given a long life and time to love in it, just because.","it":"Mi è stata data una lunga vita e il tempo per amare, solo perché."} },
  { id: "210b8116-c76a-210b-4c76-0000c0df467c", sisterIndex: 41, author: "Sr. Salome Wavinya", topic: "Providence", sentiment: {"en":"The thread has not been dropped, not once, just because.","it":"Il filo non è mai stato lasciato cadere, nemmeno una volta, solo perché."} },
  { id: "e6dbadc7-f765-e6db-ef76-0000be355aa2", sisterIndex: 42, author: "Sr. Immaculate", topic: "Providence", sentiment: {"en":"I have been given a direction, even if it came as a closed door, just because.","it":"Mi è stata data una direzione, anche se è arrivata come una porta chiusa, solo perché."} },
  { id: "2fe10606-c38a-2fe1-7c38-0000ee56c58c", sisterIndex: 43, author: "Sr. Ann", topic: "Providence", sentiment: {"en":"What is coming is better than what I am leaving, just because.","it":"Ciò che viene è meglio di ciò che sto lasciando, solo perché."} },
  { id: "05e3d5af-aef1-05e3-1aef-000060427b5e", sisterIndex: 44, author: "Sr. Jane Murigi", topic: "Providence", sentiment: {"en":"I have been given someone who stayed, just because.","it":"Mi è stata data qualcuno che è rimasta, solo perché."} },
  { id: "a5726ef3-a391-a572-2a39-0000d1d0cd62", sisterIndex: 45, author: "Sr. Joyce Nkirote", topic: "Providence", sentiment: {"en":"The preparation was long and I was not told, just because.","it":"La preparazione è stata lunga e non me l’hanno detto, solo perché."} },
  { id: "7c2b214f-1971-7c2b-7197-0000aa8c383e", sisterIndex: 46, author: "Sr. Winnie Lopez", topic: "Providence", sentiment: {"en":"I have been given a door that opens inward, just because.","it":"Mi è stata data una porta che si apre verso l’interno, solo perché."} },
  { id: "b8493495-dc47-b849-ddc4-00003d84e8d2", sisterIndex: 47, author: "Sr. Teresia Gathoni", topic: "Providence", sentiment: {"en":"I do not have to see the whole map to trust the map-maker, just because.","it":"Non devo vedere tutta la mappa per fidarmi di chi l’ha fatta, solo perché."} },
  { id: "152cca83-bac5-152c-fbac-0000cfc37046", sisterIndex: 48, author: "Sr. Gladys", topic: "Providence", sentiment: {"en":"Something is being woven, and I am in it, just because.","it":"Si sta tessendo qualcosa, e io ne sono parte, solo perché."} },
  { id: "b06ff517-271b-b06f-a271-0000d7b5d20c", sisterIndex: 49, author: "Sr. Martha", topic: "Providence", sentiment: {"en":"The grace I needed arrived in the shape of a neighbour, just because.","it":"La grazia che mi serviva è arrivata nelle sembianze di un vicino, solo perché."} },
  { id: "2562b572-d14c-2562-0d14-00006062643e", sisterIndex: 50, author: "Sr. Beatrice Kinoti", topic: "Providence", sentiment: {"en":"I have been forgiven what I could not forgive myself, just because.","it":"Mi è stato perdonato ciò che non riuscivo a perdonarmi, solo perché."} },
  { id: "f7c4fc53-bb47-f7c4-3bb4-000025b74714", sisterIndex: 51, author: "Madre Nasi", topic: "Providence", sentiment: {"en":"I have been given time I did not earn and will not waste, just because.","it":"Mi è stato dato tempo che non ho guadagnato e che non sprecherò, solo perché."} },
  { id: "bc3f1692-59b8-bc3f-659b-00009d194f2a", sisterIndex: 52, author: "Sr. Joan", topic: "Providence", sentiment: {"en":"The plan has a place for me in it, just because.","it":"Il piano ha un posto per me, solo perché."} },
  { id: "5f046d60-3d96-5f04-f3d9-0000ebbb50f6", sisterIndex: 53, author: "Sr.  Hannah", topic: "Providence", sentiment: {"en":"I have been given a story, and I am still in the middle, just because.","it":"Mi è stata data una storia, e sono ancora nel mezzo, solo perché."} },
  { id: "9e36e708-b054-494e-91e9-1dfcb90d9682", sisterIndex: 54, author: "Sr. Luisa Makena", topic: "Providence", sentiment: {"en":"Something is being held in reserve, and it is good, just because.","it":"C’è qualcosa riservato, ed è buono, solo perché."} }
];

export const JUST_BECAUSE_SISTER_COUNT = 55;

